def decide(trace):
    def val(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def reset(row):
        return row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1

    def edge(row):
        return row.get('edge')

    def episode(probe):
        result = []
        start = None
        for i, row in enumerate(trace):
            active = (not reset(row)
                      and row.get('inputs', {}).get('ena') == 1
                      and bool(val(row, probe)))
            if active and start is None:
                start = i
            if not active and start is not None:
                result.append((start, i - 1))
                start = None
        if start is not None:
            result.append((start, len(trace) - 1))
        return result

    def first_row(start, stop, predicate):
        for j in range(start, stop + 1):
            if predicate(trace[j]):
                return j
        return None

    def ordered(start, stop, predicates):
        pos = start
        found = []
        for predicate in predicates:
            j = first_row(pos, stop, predicate)
            if j is None:
                return None
            found.append(j)
            pos = j + 1
        return found

    failures = []
    activated = False

    command_probes = ('start_sequence', 'stop_sequence', 'write_sequence', 'read_sequence')
    all_command_starts = []
    for probe in command_probes:
        for start, stop in episode(probe):
            activated = True
            all_command_starts.append(start)
            if probe == 'start_sequence':
                seq = ordered(
                    start, stop,
                    [lambda r: val(r, 'scl_oen') == 1 and val(r, 'sda_oen') == 0,
                     lambda r: val(r, 'scl_oen') == 0])
                if seq is None:
                    failures.append((False, edge(trace[start]),
                                     'START sequence did not drive SDA low while SCL was released, then drive SCL low'))
            elif probe == 'stop_sequence':
                seq = ordered(
                    start, stop,
                    [lambda r: val(r, 'sda_oen') == 0,
                     lambda r: val(r, 'scl_oen') == 1,
                     lambda r: val(r, 'sda_oen') == 1])
                if seq is None:
                    failures.append((False, edge(trace[start]),
                                     'STOP sequence did not drive SDA low, release SCL, then release SDA'))
            elif probe == 'write_sequence':
                expected_sda = 0 if trace[start].get('inputs', {}).get('din') == 0 else 1
                seq = ordered(
                    start, stop,
                    [lambda r, e=expected_sda: val(r, 'sda_oen') == e,
                     lambda r: val(r, 'scl_oen') == 1,
                     lambda r: val(r, 'scl_oen') == 0])
                if seq is None:
                    failures.append((False, edge(trace[start]),
                                     'WRITE sequence did not apply din to SDA output-enable and complete an SCL high/low phase'))
            else:
                seq = ordered(
                    start, stop,
                    [lambda r: val(r, 'sda_oen') == 1,
                     lambda r: val(r, 'scl_oen') == 1,
                     lambda r: val(r, 'scl_oen') == 0])
                if seq is None:
                    failures.append((False, edge(trace[start]),
                                     'READ sequence did not release SDA and complete an SCL high/low sampling phase'))

            limit = len(trace) - 1
            for other in all_command_starts:
                if other > start:
                    limit = min(limit, other - 1)
            ack = first_row(stop, limit, lambda r: val(r, 'cmd_ack') == 1)
            aborted = first_row(start, limit, lambda r: val(r, 'al') == 1)
            if ack is None and aborted is None:
                failures.append((False, edge(trace[stop]),
                                 'completed supported command produced no cmd_ack'))

    for start, stop in episode('read_sequence'):
        rises = [j for j in range(start, stop + 1) if val(trace[j], 'filtered_scl_rise')]
        for j in rises:
            activated = True
            sampled = val(trace[j], 'ssda')
            k = first_row(j, stop, lambda r, sampled=sampled: val(r, 'dout') == sampled)
            if k is None:
                failures.append((False, edge(trace[j]),
                                 'dout did not report the filtered SDA value at a READ filtered-SCL rising event'))

    for probe, target in (('sta_condition', 1), ('sto_condition', 0)):
        for start, stop in episode(probe):
            activated = True
            j = first_row(start + 1, len(trace) - 1,
                          lambda r, target=target: val(r, 'busy') == target)
            if j is None:
                failures.append((False, edge(trace[start]),
                                 'busy did not respond to the filtered START/STOP condition'))

    for start, stop in episode('active_command'):
        loss = first_row(start, stop, lambda r: val(r, 'al') == 1)
        if loss is not None:
            activated = True
            j = first_row(loss, len(trace) - 1,
                          lambda r: val(r, 'al') == 1 and val(r, 'scl_oen') == 1 and val(r, 'sda_oen') == 1)
            if j is None:
                failures.append((False, edge(trace[loss]),
                                 'arbitration loss did not assert al and release both bus lines'))

    for probe in ('slave_wait', 'scl_sync'):
        for start, stop in episode(probe):
            activated = True
            bad = first_row(start, stop, lambda r: val(r, 'scl_oen') != 1)
            if bad is not None:
                failures.append((False, edge(trace[bad]),
                                 probe + ' occurred without keeping SCL released'))

    if failures:
        return failures[0]
    if not activated:
        return (None, None, 'no enabled supported command or relevant filtered bus activity occurred')
    return (True, None, 'supported command and filtered bus-operation observations satisfied')

def decide(trace):
    if not trace:
        return (None, None, 'no trace states were provided; open-drain behavior was not observed')

    for row in trace:
        outputs = row['outputs']
        edge = row['edge']

        scl_o = outputs['scl_o']
        sda_o = outputs['sda_o']
        scl_oen = outputs['scl_oen']
        sda_oen = outputs['sda_oen']

        if scl_oen not in (0, 1):
            return (False, edge, f"scl_oen is {scl_oen}; active-low open-drain control requires 0 for drive or 1 for release")
        if sda_oen not in (0, 1):
            return (False, edge, f"sda_oen is {sda_oen}; active-low open-drain control requires 0 for drive or 1 for release")

        if scl_o != 0:
            mode = 'drive' if scl_oen == 0 else 'release'
            return (False, edge, f"scl_o is {scl_o} while scl_oen selects {mode}; the open-drain drive value must remain low (0)")
        if sda_o != 0:
            mode = 'drive' if sda_oen == 0 else 'release'
            return (False, edge, f"sda_o is {sda_o} while sda_oen selects {mode}; the open-drain drive value must remain low (0)")

    return (True, trace[-1]['edge'], 'scl_o and sda_o remained low for both active-low drive/release control states')

def decide(trace):
    if not trace:
        return (None, None, 'the activation never occurred; there are no clock-edge states')

    for row in trace:
        outputs = row.get('outputs', {})
        edge = row.get('edge')

        if outputs.get('scl_o') != 0:
            return (False, edge, 'scl_o is not constant low as required')
        if outputs.get('sda_o') != 0:
            return (False, edge, 'sda_o is not constant low as required')

        # The two enable ports are one-bit declared controls. Their active-low
        # interpretation is part of the interface definition, but no separate
        # external line or ownership observation is declared here from which
        # the polarity could be behaviorally distinguished.
        for port in ('scl_oen', 'sda_oen'):
            if outputs.get(port) not in (0, 1):
                return (False, edge,
                        f'{port} is not a valid one-bit active-low control value')

    return (True, None,
            'scl_o and sda_o remained constant low; active-low enable polarity is not independently observable')

def decide(trace):
    if not trace:
        return (None, None, 'no output-enable observation occurred')

    saw_scl = False
    saw_sda = False
    for row in trace:
        outputs = row['outputs']
        scl_oen = outputs.get('scl_oen')
        sda_oen = outputs.get('sda_oen')

        if scl_oen in (0, 1):
            saw_scl = True
            if outputs.get('scl_o') != 0:
                mode = 'drive low' if scl_oen == 0 else 'release'
                return (False, row['edge'],
                        f'scl_oen={scl_oen} selects {mode}, but scl_o is not the required low open-drain drive value 0')

        if sda_oen in (0, 1):
            saw_sda = True
            if outputs.get('sda_o') != 0:
                mode = 'drive low' if sda_oen == 0 else 'release'
                return (False, row['edge'],
                        f'sda_oen={sda_oen} selects {mode}, but sda_o is not the required low open-drain drive value 0')

    if not saw_scl and not saw_sda:
        return (None, None, 'no declared output-enable observation occurred')
    return (True, None, 'each observed low or released output-enable state uses the low open-drain drive value; external line pull-up behavior is outside the module')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def active(row):
        return (row['inputs'].get('ena') == 1
                and row['outputs'].get('active_command') == 1)

    def closes(row):
        return row['outputs'].get('cmd_ack') == 1

    def aborts(row):
        return (row['outputs'].get('al') == 1
                or row['inputs'].get('nReset') == 0
                or row['inputs'].get('rst') == 1)

    windows = after(trace, active, until=closes, aborts=aborts)

    def line_controlled(row):
        return (row['outputs'].get('scl_oen') != 1
                or row['outputs'].get('sda_oen') != 1)

    return worst([
        eventually(w, line_controlled, strong=False, after_activation=True)
        for w in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import after, sequence, worst

    def holds(**values):
        def predicate(row):
            for port, value in values.items():
                if row['outputs'].get(port) != value:
                    return False
            return True
        return predicate

    def any_condition(*conditions):
        def predicate(row):
            return any(condition(row) for condition in conditions)
        return predicate

    aborts = any_condition(
        holds(al=1),
        lambda row: row['inputs'].get('nReset') == 0,
        lambda row: row['inputs'].get('rst') == 1,
    )

    def command_windows(probe):
        return after(
            trace,
            lambda row: row['outputs'].get(probe) == 1,
            until=holds(cmd_ack=1),
            aborts=aborts,
        )

    checks = []

    # START: release both lines, drive SDA low while SCL is released,
    # then drive SCL low.
    for window in command_windows('start_sequence'):
        checks.append(sequence(
            window,
            holds(scl_oen=1, sda_oen=1),
            holds(scl_oen=1, sda_oen=0),
            holds(scl_oen=0, sda_oen=0),
            strong=False,
        ))

    # STOP: drive SDA low, release SCL, then release SDA while SCL is high.
    for window in command_windows('stop_sequence'):
        checks.append(sequence(
            window,
            holds(scl_oen=0, sda_oen=0),
            holds(scl_oen=1, sda_oen=0),
            holds(scl_oen=1, sda_oen=1),
            strong=False,
        ))

    # READ: release SDA and SCL for the sample window, then drive SCL low.
    for window in command_windows('read_sequence'):
        checks.append(sequence(
            window,
            holds(scl_oen=1, sda_oen=1),
            holds(scl_oen=0, sda_oen=1),
            strong=False,
        ))

    # WRITE: set SDA from din, release SCL for the high phase, then drive
    # SCL low again.  din is stimulus qualification, not an observable effect.
    for window in command_windows('write_sequence'):
        sda_level = 0 if window.value('din') == 0 else 1
        checks.append(sequence(
            window,
            lambda row, value=sda_level: (
                row['outputs'].get('sda_oen') == value and
                row['outputs'].get('scl_oen') == 0
            ),
            lambda row, value=sda_level: (
                row['outputs'].get('sda_oen') == value and
                row['outputs'].get('scl_oen') == 1
            ),
            lambda row, value=sda_level: (
                row['outputs'].get('sda_oen') == value and
                row['outputs'].get('scl_oen') == 0
            ),
            strong=False,
        ))

    return worst(checks)

def decide(trace):
    completions = []
    failures = []
    saw_incomplete = False

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})

        # A supported command completion is the transition from an active
        # command to idle without arbitration loss.  Reset/abort traces do not
        # constitute completion windows for this routed observation.
        if (prev_out.get('active_command') == 1 and
                out.get('active_command') == 0 and
                out.get('idle') == 1 and
                out.get('al', 0) == 0):
            completions.append(row)
            ack = out.get('cmd_ack')
            if ack != 1:
                failures.append((row['edge'], 'cmd_ack was not asserted at command completion'))
                continue
            if row.get('held', 0) != 1:
                failures.append((row['edge'],
                                 'cmd_ack was asserted for more than one clock interval'))
                continue

            if i + 1 >= len(trace):
                saw_incomplete = True
            else:
                following = trace[i + 1]
                if following.get('outputs', {}).get('cmd_ack') == 1:
                    failures.append((following['edge'],
                                     'cmd_ack remained asserted on the following clock state'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not completions:
        return (None, None, 'no supported command completion occurred in this trace')
    if saw_incomplete:
        return (None, completions[-1]['edge'],
                'cmd_ack was observed at completion, but the following clock state was not present')
    return (True, completions[-1]['edge'],
            'cmd_ack asserted for exactly one clock interval at each observed command completion')

def decide(trace):
    completions = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        po = prev.get('outputs', {})
        o = row.get('outputs', {})
        pi = prev.get('inputs', {})
        inp = row.get('inputs', {})

        # A command completion is the declared active-command probe
        # transitioning to the declared idle probe. Reset and arbitration
        # loss terminate a command without completing it.
        if (po.get('active_command') == 1 and
                o.get('active_command') == 0 and
                o.get('idle') == 1 and
                po.get('al', 0) == 0 and o.get('al', 0) == 0 and
                pi.get('nReset', 1) == 1 and inp.get('nReset', 1) == 1 and
                pi.get('rst', 0) == 0 and inp.get('rst', 0) == 0):
            completions.append(i)

    if not completions:
        return (None, None, 'no non-aborted active-command-to-idle completion occurred')

    for i in completions:
        row = trace[i]
        o = row.get('outputs', {})
        edge = row.get('edge')

        if o.get('cmd_ack') != 1:
            return (False, edge,
                    'at command completion, cmd_ack was not asserted on the rising-edge state')

        high_edges = row.get('held', 1)
        j = i + 1
        while j < len(trace) and trace[j].get('outputs', {}).get('cmd_ack') == 1:
            high_edges += trace[j].get('held', 1)
            j += 1

        if high_edges != 1:
            return (False, edge,
                    'cmd_ack did not remain asserted for exactly one clock edge at completion')

        if j >= len(trace):
            return (None, edge,
                    'completion was observed, but the trace ended before cmd_ack deassertion could be sampled')

        if trace[j].get('outputs', {}).get('cmd_ack') != 0:
            return (False, trace[j].get('edge'),
                    'cmd_ack did not deassert after the one-clock completion pulse')

    return (True, None,
            'cmd_ack asserted at each non-aborted command completion and deasserted after the one-clock pulse')

def decide(trace):
    activations = []
    previous_rst = None

    for row in trace:
        rst = row['inputs'].get('rst')
        if rst == 1 and (previous_rst is None or previous_rst == 0):
            activations.append(row)
        previous_rst = rst

    if not activations:
        return (None, None, 'no synchronous reset assertion edge occurred')

    for row in activations:
        out = row['outputs']
        expected = {
            'cmd_ack': 0,
            'busy': 0,
            'al': 0,
            'scl_oen': 1,
            'sda_oen': 1,
        }
        bad = [
            port for port, value in expected.items()
            if out.get(port) != value
        ]
        if bad:
            details = ', '.join(
                f'{port}={out.get(port)!r}, expected {expected[port]}'
                for port in bad
            )
            return (False, row['edge'],
                    f'synchronous reset edge did not reset observable outputs: {details}')

    return (True, activations[-1]['edge'],
            'all observable reset outputs were reset at each synchronous rst assertion edge')

def decide(trace):
    episodes = []
    i = 0

    while i < len(trace):
        inputs = trace[i].get('inputs', {})
        if inputs.get('nReset') != 0:
            i += 1
            continue

        start = i
        while i < len(trace) and trace[i].get('inputs', {}).get('nReset') == 0:
            i += 1
        episodes.append((start, i))

    if not episodes:
        return (None, None, 'nReset was never observed asserted low')

    for start, end in episodes:
        for row in trace[start:end]:
            if row.get('outputs', {}).get('scl_oen') != 1:
                return (
                    False,
                    row.get('edge'),
                    'while nReset was low, scl_oen was not high; the asynchronous reset state was not maintained'
                )

    first_edge = trace[episodes[0][0]].get('edge')
    return (
        True,
        first_edge,
        f'scl_oen was high throughout all {len(episodes)} observed nReset-low reset episode(s)'
    )

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def reset_deasserted(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset', 1) == 1 and inputs.get('rst', 0) == 0

    sequences = ('start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence')
    enabled_seen = False
    disabled_seen = False

    # Enabled command observations: use the declared sequence probes as the
    # state-dependent trigger, then look forward for the routed completion ack.
    for i, row in enumerate(trace):
        if (row.get('inputs', {}).get('ena') == 1 and reset_deasserted(row)
                and any(out(row, p) == 1 for p in sequences)
                and (i == 0 or not any(out(trace[i - 1], p) == 1 for p in sequences))):
            enabled_seen = True
            ack_index = None
            for j in range(i + 1, len(trace)):
                candidate = trace[j]
                if not reset_deasserted(candidate) or out(candidate, 'al') == 1:
                    break
                if out(candidate, 'cmd_ack') == 1:
                    ack_index = j
                    break
            if ack_index is None:
                continue
            ack = trace[ack_index]
            if ack.get('held') != 1:
                return (False, ack.get('edge'),
                        'with ena=1, cmd_ack was not high for exactly one clock cycle')

    # Disabled observations: the idle probe scopes the held ena input to the
    # state in which no command is being accepted or progressed.
    for row in trace:
        if (row.get('inputs', {}).get('ena') == 0 and reset_deasserted(row)
                and out(row, 'idle') == 1):
            disabled_seen = True
            if out(row, 'cmd_ack') == 1:
                return (False, row.get('edge'),
                        'with ena=0 in idle, cmd_ack pulsed although command acceptance is disabled')

    if not enabled_seen or not disabled_seen:
        return (None, None,
                'the routed ena observation needs both a reachable enabled command sequence and a reset-deasserted idle interval with ena=0')
    return (True, None,
            'ena was observed both enabling command completion and suppressing cmd_ack while idle')

def decide(trace):
    from specflow.refmodel.temporal import after, edges, stable, throughout, worst

    def out(row, name):
        return row['outputs'].get(name)

    def ena_low(row):
        return row['inputs'].get('ena') == 0

    def ena_high(row):
        return row['inputs'].get('ena') == 1

    def active_command(row):
        return out(row, 'active_command') == 1

    ena_falls = edges(trace, 'ena', 'fall')
    scl_windows = after(
        trace,
        lambda r: r['edge'] in ena_falls
        and ena_low(r)
        and active_command(r),
        until=ena_high,
    )

    scl_verdicts = [
        stable(window, 'scl_oen', after_activation=False)
        for window in scl_windows
    ]

    filtered_starts = edges(trace, 'sta_condition', 'rise')
    filtered_stops = edges(trace, 'sto_condition', 'rise')
    filtered_events = filtered_starts | filtered_stops
    busy_windows = after(
        trace,
        lambda r: r['edge'] in filtered_events and ena_low(r),
        until=ena_high,
    )

    busy_verdicts = [
        throughout(
            window,
            lambda r: out(r, 'busy') == window.value('busy'),
            after_activation=False,
        )
        for window in busy_windows
    ]

    return worst(scl_verdicts + busy_verdicts)

def decide(trace):
    for row in trace:
        if (row['inputs'].get('ena') == 1 and
                row['outputs'].get('filter_cnt') == 1):
            return (True, row['edge'],
                    'filter_cnt reached while filter timing was enabled; the specification does not state a numeric sampling interval or transformation to check')
    return (None, None,
            'filter_cnt was not reached while ena was high; no filter sampling interval was exercised in this trace')

from specflow.refmodel.temporal import TO_END, after, eventually, worst

def decide(trace):
    def holds(row, cond):
        values = {}
        values.update(row.get('inputs', {}))
        values.update(row.get('outputs', {}))
        return all(values.get(port) == value for port, value in cond.items())

    windows = after(
        trace,
        lambda row: holds(row, {'idle': 1, 'cmd': 1}),
        until=TO_END
    )

    return worst([
        eventually(
            window,
            lambda row: holds(row, {'start_sequence': 1}),
            after_activation=True,
            strong=True
        )
        for window in windows
    ])

from specflow.refmodel.temporal import TO_END, after, eventually, worst

def decide(trace):
    def applies(row):
        return (
            row['outputs'].get('idle', 0) == 1
            and row['inputs'].get('cmd') == 2
            and row['inputs'].get('ena') == 1
        )

    def reset_active(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        applies,
        until=TO_END,
        aborts=reset_active,
    )
    return worst([
        eventually(
            window,
            lambda row: row['outputs'].get('cmd_ack') == 1,
            strong=True,
            after_activation=False,
        )
        for window in windows
    ])

def decide(trace):
    unsupported = {0, 3, 5, 6, 7, 9, 10, 11, 12, 13, 14, 15}
    valid = {1, 2, 4, 8}
    saw_activation = False
    active = False

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        cmd = inputs.get('cmd')
        idle = outputs.get('idle')

        if not active:
            if idle == 1 and cmd in unsupported:
                active = True
                saw_activation = True
            else:
                continue

        if cmd in valid:
            active = False
            continue

        if cmd in unsupported and idle != 1:
            return (False, row.get('edge'),
                    'FSM left idle while an unsupported or idle command was driven')

    if not saw_activation:
        return (None, None,
                'no unsupported or idle command was observed while the FSM was idle')
    return (True, None,
            'FSM remained idle throughout each observed unsupported or idle-command occurrence')

from specflow.refmodel.temporal import after, eventually, worst

def decide(trace):
    def holds(row, cond):
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        return all(outputs.get(port, inputs.get(port)) == value
                   for port, value in cond.items())

    def opens(row):
        inputs = row.get('inputs', {})
        return (
            holds(row, {'write_sequence': 1})
            and inputs.get('cmd') == 4
            and inputs.get('ena') == 1
            and inputs.get('din') in (0, 1)
        )

    def closes(row):
        return row.get('outputs', {}).get('cmd_ack') == 1

    def aborts(row):
        return (
            row.get('outputs', {}).get('al') == 1
            or row.get('inputs', {}).get('nReset') == 0
            or row.get('inputs', {}).get('rst') == 1
        )

    windows = after(trace, opens, until=closes, aborts=aborts)
    verdicts = []
    for window in windows:
        expected = window.value('din')
        verdicts.append(
            eventually(
