def decide(trace):
    failures = []
    saw_effect = False

    def enabled(row):
        inp = row.get('inputs', {})
        return (inp.get('ena') == 1 and
                inp.get('nReset') == 1 and
                inp.get('rst') == 0)

    def out(row, name):
        return row.get('outputs', {}).get(name)

    # Qualified filtered START/STOP events must be the events that affect busy.
    for row in trace:
        if not enabled(row):
            continue
        if out(row, 'sta_condition'):
            saw_effect = True
            if out(row, 'busy') != 1:
                failures.append((row.get('edge'),
                                 'qualified filtered START did not set busy'))
        if out(row, 'sto_condition'):
            saw_effect = True
            if out(row, 'busy') != 0:
                failures.append((row.get('edge'),
                                 'qualified filtered STOP did not clear busy'))

    # A READ samples the filtered SDA value only at a qualified filtered SCL rise.
    for row in trace:
        if not enabled(row):
            continue
        if out(row, 'read_sequence') and out(row, 'filtered_scl_rise'):
            saw_effect = True
            if out(row, 'dout') != out(row, 'ssda'):
                failures.append((row.get('edge'),
                                 'dout did not capture filtered SDA at the filtered SCL rising edge'))

    # Clock stretching: while the controller is waiting for released SCL to
    # become high, command completion must not be acknowledged.  If the
    # command survives the wait, a later acknowledgement must be observable;
    # an abruptly truncated or aborted attempt remains undecided.
    i = 0
    while i < len(trace):
        row = trace[i]
        if not (enabled(row) and out(row, 'slave_wait')):
            i += 1
            continue

        start = i
        saw_active = False
        while i < len(trace) and enabled(trace[i]) and out(trace[i], 'slave_wait'):
            if out(trace[i], 'active_command'):
                saw_active = True
            if out(trace[i], 'cmd_ack'):
                failures.append((trace[i].get('edge'),
                                 'cmd_ack asserted while filtered SCL was still low in slave_wait'))
            i += 1
        end = i

        if not saw_active:
            continue

        later_ack = False
        aborted = False
        for j in range(end, len(trace)):
            if not enabled(trace[j]):
                break
            if out(trace[j], 'al'):
                aborted = True
                break
            if out(trace[j], 'cmd_ack'):
                later_ack = True
                break
        if later_ack:
            saw_effect = True
        elif not aborted:
            # The wait was exercised, but the trace ended or stopped before a
            # surviving command demonstrated its postponed completion.
            pass

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not saw_effect:
        return (None, None, 'no qualified filtered SCL consequence was exercised')
    return (True, None, 'scl_i consequences were observed only through qualified filtered events')

def decide(trace):
    def value(row, name):
        return row.get('outputs', {}).get(name)

    def usable(row):
        inputs = row.get('inputs', {})
        return (inputs.get('ena') == 1 and
                inputs.get('nReset') != 0 and
                inputs.get('rst') != 1)

    def rising(i, predicate):
        if not predicate(trace[i]):
            return False
        return i == 0 or not predicate(trace[i - 1])

    def find_level(start, port, expected, stop=None):
        end = len(trace) if stop is None else min(stop, len(trace))
        for j in range(start, end):
            if not usable(trace[j]):
                return None, True
            if value(trace[j], port) == expected:
                return trace[j], False
        return None, False

    events = []

    # A filtered START or STOP probe is the situation in which SDA is used
    # for bus-status detection.  The output may respond in a later state.
    for i, row in enumerate(trace):
        if not usable(row):
            continue

        is_start = rising(i, lambda r: value(r, 'sta_condition') == 1)
        is_stop = rising(i, lambda r: value(r, 'sto_condition') == 1)
        if is_start or is_stop:
            expected = 1 if is_start else 0
            found, aborted = find_level(i, 'busy', expected)
            if aborted:
                continue
            if found is None:
                if i == len(trace) - 1:
                    return (None, None,
                            'the filtered START/STOP detection window reached the end before busy responded')
                return (False, row.get('edge'),
                        'busy did not reflect the synchronized and filtered SDA START/STOP detection')
            events.append(found)

    # A low filtered SDA during the released-high WRITE arbitration phase is
    # the only SDA condition that obliges arbitration status to assert.
    def arbitration_phase(r):
        return (value(r, 'write_sequence') == 1 and
                value(r, 'sda_chk') == 1 and
                r.get('inputs', {}).get('din') == 1 and
                value(r, 'ssda') == 0 and
                value(r, 'al') == 0)

    for i, row in enumerate(trace):
        if not usable(row) or not rising(i, arbitration_phase):
            continue
        found = None
        ended = False
        for j in range(i, len(trace)):
            candidate = trace[j]
            if not usable(candidate):
                ended = True
                break
            if value(candidate, 'al') == 1:
                found = candidate
                break
            if j > i and value(candidate, 'write_sequence') != 1:
                ended = True
                break
        if found is not None:
            events.append(found)
        elif ended:
            return (False, row.get('edge'),
                    'al did not assert for synchronized and filtered low SDA during released-high WRITE arbitration')
        else:
            return (None, None,
                    'the filtered WRITE arbitration window reached the end before al responded')

    # At a filtered SCL rising edge in READ, dout must eventually show the
    # filtered SDA sample.  No particular registered-output latency is fixed.
    def read_sample(r):
        return (value(r, 'read_sequence') == 1 and
                value(r, 'filtered_scl_rise') == 1)

    for i, row in enumerate(trace):
        if not usable(row) or not rising(i, read_sample):
            continue
        expected = value(row, 'ssda')
        found = None
        ended = False
        for j in range(i, len(trace)):
            candidate = trace[j]
            if not usable(candidate):
                ended = True
                break
            if value(candidate, 'dout') == expected:
                found = candidate
                break
            if j > i and value(candidate, 'read_sequence') != 1:
                ended = True
                break
        if found is not None:
            events.append(found)
        elif ended:
            return (False, row.get('edge'),
                    'dout did not reflect the synchronized and filtered SDA value at the READ sampling edge')
        else:
            return (None, None,
                    'the filtered READ sampling window reached the end before dout reflected SDA')

    if not events:
        return (None, None,
                'no filtered START/STOP, WRITE arbitration, or READ sampling situation occurred')

    return (True, events[-1].get('edge'),
            'SDA-dependent outputs were checked only at declared synchronized and filtered use situations')

def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def value(row, port):
        return row.get('outputs', {}).get(port, 0)

    def aborted(row):
        return (value(row, 'al') == 1 or
                row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    completions = []
    starts = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        for port in sequence_ports:
            if value(previous, port) == 1 and value(current, port) != 1:
                if not aborted(current):
                    completions.append(i)
            if value(previous, port) != 1 and value(current, port) == 1:
                starts.append(i)

    if not completions:
        return (None, None,
                'no non-aborted START, STOP, READ, or WRITE command completion occurred')

    verdicts = []
    for completion in completions:
        next_start = min((i for i in starts if i > completion),
                         default=len(trace))
        rows = trace[completion:next_start]

        episodes = []
        i = 0
        while i < len(rows):
            if value(rows[i], 'cmd_ack') != 1:
                i += 1
                continue
            total_edges = 0
            first = i
            while i < len(rows) and value(rows[i], 'cmd_ack') == 1:
                total_edges += rows[i].get('held', 1)
                i += 1
            episodes.append((first, total_edges))

        if len(episodes) != 1:
            verdicts.append((False, trace[completion].get('edge'),
                             'command completion required exactly one cmd_ack pulse, '
                             f'but this transaction contained {len(episodes)}'))
        elif episodes[0][1] != 1:
            verdicts.append((False, rows[episodes[0][0]].get('edge'),
                             'cmd_ack was asserted for '
                             f'{episodes[0][1]} clock edges; exactly one was required'))
        else:
            verdicts.append((True, rows[episodes[0][0]].get('edge'),
                             'cmd_ack was asserted for exactly one clock edge after command completion'))

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    return (True, None,
            f'{len(verdicts)} non-aborted command completion(s) each had one-clock cmd_ack')

