            edge = trace[updates[n + 1][0]].get('edge')
            return (
                False,
                edge,
                f"after a filter sample update, sscl/ssda did not reach "
                f"the majority values {expected_scl}/{expected_sda} of the "
                f"three-sample fscl/fsda histories before the next update"
            )

        if not matched:
            return (
                None,
                None,
                'the final filter-sample window ended before the majority result was observable'
