            end = None
            for j in range(i + 1, len(trace)):
                if trace[j]["inputs"].get(port) == before:
                    end = j
                    break
            if end is None:
                continue

            prior = [v for k, v in samples if k < i]
            differing = [v for k, v in samples if i <= k <= end and v != before]
            if len(prior) < 2 or prior[-1] != before or prior[-2] != before:
                continue
            if len(differing) > 1:
                continue

            exercised = True
            for k in range(i, end + 1):
                if out(trace[k], filtered) != out(trace[i - 1], filtered):
                    failures.append((trace[k].get("edge"), port, filtered))
                    break

