def decide(trace):
    def outputs(row):
        return row.get('outputs', {})

    def inputs(row):
        return row.get('inputs', {})

    def reset_active(row):
        inp = inputs(row)
        return inp.get('nReset') == 0 or inp.get('rst') == 1

    def sequence_active(row):
        out = outputs(row)
        return any(out.get(name, 0) == 1 for name in (
            'start_sequence',
            'stop_sequence',
            'read_sequence',
            'write_sequence',
        ))

    def supported_and_enabled(row):
        inp = inputs(row)
        return inp.get('ena') == 1 and inp.get('cmd') in (1, 2, 4, 8)

    def pulse_verdict(start, completion):
        first = start
        while first < len(trace) and outputs(trace[first]).get('cmd_ack') != 1:
            first += 1

        if first == len(trace):
            return (False, trace[completion].get('edge'),
                    'command sequence completed without the required cmd_ack pulse')

        if first < completion:
            return (False, trace[first].get('edge'),
                    'cmd_ack asserted before the command sequence ended')

        if outputs(trace[first]).get('idle') != 1:
            return (False, trace[first].get('edge'),
                    'cmd_ack asserted while the FSM was not idle')

        total_edges = 0
        j = first
        while j < len(trace) and outputs(trace[j]).get('cmd_ack') == 1:
            total_edges += trace[j].get('held', 0)
            j += 1

        if j == len(trace):
            return (None, None,
                    'cmd_ack was high when the trace ended; the pulse width is incomplete')

        if total_edges != 1:
            return (False, trace[first].get('edge'),
                    f'cmd_ack was high for {total_edges} clock edges, expected exactly one')

        return (True, trace[first].get('edge'),
                'the FSM returned to idle and cmd_ack pulsed high for exactly one clock cycle')

    pending = False
    completed = False
    completion_index = None
    saw_activation = False
    verdicts = []

    for i, row in enumerate(trace):
        if reset_active(row):
            pending = False
            completion_index = None
            continue

        out = outputs(row)
        active = sequence_active(row)
        previous_active = sequence_active(trace[i - 1]) if i else False

        if not pending and not completed and active and not previous_active:
            if supported_and_enabled(row) and out.get('al', 0) != 1:
                pending = True
                saw_activation = True

        if not pending:
            continue

        if out.get('al') == 1:
            pending = False
            completion_index = None
            continue

        if out.get('cmd_ack') == 1 and active:
            verdicts.append((False, row.get('edge'),
                             'cmd_ack asserted before the command sequence ended'))
            pending = False
            completion_index = None
            completed = True
            continue

        if not active:
            completion_index = i
            verdicts.append(pulse_verdict(i, completion_index))
            pending = False
            completed = True

    if pending:
        return (None, None,
                'the supported command sequence was still active when the trace ended')

    if verdicts:
        failures = [v for v in verdicts if v[0] is False]
        if failures:
            return failures[0]
        decisions = [v for v in verdicts if v[0] is not None]
        if decisions:
            return decisions[0]
        return verdicts[0]

    if not saw_activation:
        return (None, None, 'no enabled supported command sequence began in this trace')

    return (None, None, 'no completed command sequence was observed')

