            current['inputs'].get('ena') == 1 and
            out(previous, 'slave_wait') == 0 and
            out(current, 'slave_wait') == 0 and
            out(current, 'sscl') == 1 and
            out(previous, 'scl_oen') == 1 and
            out(current, 'scl_oen') != 1
