    def value(row, name):
        return row.get('outputs', {}).get(name)

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    def in_start(row):
        return bool(value(row, 'start_sequence'))

    def starts_of_sequence():
        result = []
        for i, row in enumerate(trace):
            if reset_active(row) or not in_start(row):
                continue
            if i == 0 or not in_start(trace[i - 1]):
                result.append(i)
        return result

    starts = starts_of_sequence()
    if not starts:
        return (None, None,
                'START command sequence never occurred; no START transaction was exercised')

    for start in starts:
        end = len(trace)
        aborted = False
        for k in range(start, len(trace)):
            if reset_active(trace[k]):
                aborted = True
                break
            if k > start and not in_start(trace[k]):
                end = k
                break

        if aborted:
            continue

        # The initial release may already have happened when the sequence
        # probe becomes true.  Find the required START-condition state,
        # including the activation row itself.
        sda_low = None
        for j in range(start, end):
            if (value(trace[j], 'sda_oen') == 0 and
                    value(trace[j], 'scl_oen') == 1):
                sda_low = j
                break

        if sda_low is None:
            if end == len(trace) and in_start(trace[-1]):
                return (None, None,
                        'START sequence is still active; SDA-low while SCL is released has not yet been observed')
            return (False, trace[start]['edge'],
                    'START sequence did not pull SDA low while SCL remained released')

        scl_low = None
        for j in range(sda_low, end):
            if value(trace[j], 'scl_oen') == 0:
                scl_low = j
                break

        if scl_low is None:
            if end == len(trace) and in_start(trace[-1]):
                return (None, None,
                        'START sequence is still active; SCL-low completion phase has not yet been observed')
            return (False, trace[sda_low]['edge'],
                    'START sequence did not pull SCL low after the SDA-low START condition')

        idle = None
        for j in range(scl_low, end):
            if value(trace[j], 'idle'):
                idle = j
                break

        if idle is None:
            if end == len(trace) and in_start(trace[-1]):
                return (None, None,
                        'START sequence is still active; return to idle has not yet been observed')
            return (False, trace[scl_low]['edge'],
                    'START sequence pulled SCL low but did not return the FSM to idle')

        ack = None
        for j in range(idle, end):
            if value(trace[j], 'cmd_ack') == 1:
                ack = j
                break

        if ack is None:
            if end == len(trace) and in_start(trace[-1]):
                return (None, None,
                        'START sequence is still active; cmd_ack completion pulse has not yet been observed')
            return (False, trace[idle]['edge'],
                    'START sequence returned to idle but never asserted cmd_ack')

        if value(trace[ack], 'idle') != 1:
            return (False, trace[ack]['edge'],
                    'cmd_ack was asserted before the FSM was idle')

        width = trace[ack].get('held', 1)
        if width != 1:
            return (False, trace[ack]['edge'],
                    f'cmd_ack was high for {width} edges, expected exactly one clock cycle')

        if ack + 1 >= len(trace):
            return (None, None,
                    'cmd_ack pulse begins at the end of the trace; its one-clock termination is not observable')

        if value(trace[ack + 1], 'cmd_ack') == 1:
            return (False, trace[ack]['edge'],
                    'cmd_ack remained high beyond its required one-clock pulse')

        return (True, trace[ack]['edge'],
                'START condition was generated in order, SCL was pulled low, the FSM returned to idle, and cmd_ack was high for exactly one clock cycle')

    return (None, None,
            'All observed START transactions were aborted by reset before their obligations applied')

