                    'a START, STOP, READ, or WRITE sequence remained incomplete in the trace')

        # Reset or arbitration loss voids the acknowledgement obligation.
        if any(aborted(trace[j]) for j in range(start, end + 1)):
            continue

        # cmd_ack must not occur before the sequence completion boundary.
        early = [j for j in range(start, end)
                 if out(trace[j], 'cmd_ack') == 1]
        if early:
            return (False, trace[early[0]].get('edge'),
                    'cmd_ack was asserted before the START, STOP, READ, or WRITE sequence ended')

        # The first state after the sequence is its completion state, and the
        # registered acknowledgement must be asserted there.
        if out(trace[end], 'cmd_ack') != 1:
            return (False, trace[end].get('edge'),
                    'at the end of the command sequence cmd_ack was not asserted')

        width = 0
        j = end
        while j < len(trace) and out(trace[j], 'cmd_ack') == 1:
            width += trace[j].get('held', 1)
            j += 1

        if width != 1:
            return (False, trace[end].get('edge'),
                    f'cmd_ack was asserted for {width} clk cycles at sequence completion; expected exactly one')

        completed += 1

    if completed == 0:
        return (None, None,
                'no non-aborted START, STOP, READ, or WRITE sequence reached completion')

    return (True, None,
            f'{completed} completed START, STOP, READ, or WRITE sequence(s) had exactly one clk-cycle cmd_ack pulse')

def decide(trace):
    active = False
    start = None
    aborted = False
    incomplete = False
    completed = 0

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        is_reset = inputs.get('nReset') == 0 or inputs.get('rst') == 1
        is_active = outputs.get('active_command') == 1
        is_al = outputs.get('al') == 1
        ack = outputs.get('cmd_ack')

        if is_reset:
            active = False
            start = None
            aborted = False
            continue

        if not active:
            if is_active:
                active = True
                start = i
                aborted = is_al
            continue

        if is_al:
            aborted = True

        if is_active:
            if not aborted and ack == 1:
                return (False, row.get('edge'),
                        'cmd_ack was high before the bit-level operation completed')
            continue

        # The active operation has ended.  Arbitration loss makes this an
        # aborted operation rather than a completion.
        if aborted:
            active = False
            start = None
            aborted = False
            continue

        completed += 1
        if ack != 1:
            return (False, row.get('edge'),
                    'cmd_ack was not high when the bit-level operation completed')

        if start is not None and start < i:
            previous_ack = trace[i - 1].get('outputs', {}).get('cmd_ack')
            if previous_ack == 1:
                return (False, row.get('edge'),
                        'cmd_ack was already high before the completion state')

        total_edges = 0
        j = i
        while j < len(trace) and trace[j].get('outputs', {}).get('cmd_ack') == 1:
            total_edges += trace[j].get('held', 0)
            j += 1

        if j == len(trace):
            incomplete = True
        elif total_edges != 1:
            return (False, row.get('edge'),
                    f'cmd_ack was high for {total_edges} clock edges, expected exactly 1')

        active = False
        start = None
        aborted = False

    if active and not aborted:
        incomplete = True

    if completed == 0:
        return (None, None, 'no non-aborted bit-level operation reached completion')
    if incomplete:
        return (None, None, 'a bit-level operation or its cmd_ack pulse was incomplete at the end of the trace')
    return (True, None, f'cmd_ack was a one-clock pulse for {completed} completed bit-level operation(s)')

