def decide(trace):
    from specflow.refmodel.temporal import after, worst

    sequence_probes = (
        "start_sequence",
        "stop_sequence",
        "read_sequence",
        "write_sequence",
    )

    def active(row, probe):
        return row["outputs"].get(probe) == 1

    def closed(row):
        return row["outputs"].get("cmd_ack") == 1

    def aborted(row):
        return (
            row["outputs"].get("al") == 1
            or row["inputs"].get("nReset") == 0
            or row["inputs"].get("rst") == 1
        )

    verdicts = []
    for probe in sequence_probes:
        windows = after(
            trace,
            lambda row, p=probe: active(row, p),
            until=closed,
            aborts=aborted,
        )

        for window in windows:
            if not window.closed:
                verdicts.append(
                    (None, window.edge,
                     f"{probe} began but cmd_ack or completion was not observed")
                )
                continue

            rows = window.rows
            previous = {
                port: window.past(port)
                for port in ("scl_oen", "sda_oen")
            }
            changed = False
            change_edge = window.edge

            for row in rows:
                for port in ("scl_oen", "sda_oen"):
                    value = row["outputs"].get(port)
                    if value != previous[port]:
                        changed = True
                        change_edge = row["edge"]
                    previous[port] = value

            if changed:
                verdicts.append(
                    (True, change_edge,
                     f"{probe} produced a timed change on scl_oen or sda_oen")
                )
            else:
                verdicts.append(
                    (False, window.edge,
                     f"{probe} completed without a change on scl_oen or sda_oen")
                )

    return worst(verdicts)

