def decide(trace):
    from specflow.refmodel.temporal import after, edges, sequence, worst

    def out(row, name):
        return row.get("outputs", {}).get(name)

    def inp(row, name):
        return row.get("inputs", {}).get(name)

    def aborted(row):
        return (out(row, "al") == 1 or
                inp(row, "nReset") == 0 or
                inp(row, "rst") == 1)

    def level(**wanted):
        return lambda row: all(out(row, name) == value
                               for name, value in wanted.items())

    def sequence_windows(probe):
        rises = edges(trace, probe, "rise")
        return after(
            trace,
            lambda row, p=probe, rs=rises:
                row.get("edge") in rs and out(row, p) == 1 and inp(row, "ena") == 1,
            until=lambda row: out(row, "cmd_ack") == 1,
            aborts=aborted,
        )

    verdicts = []

    for window in sequence_windows("start_sequence"):
        verdicts.append(sequence(
            window,
            level(sda_oen=0, scl_oen=1),
            level(scl_oen=0),
            strong=False,
            after_activation=True,
        ))

    for window in sequence_windows("stop_sequence"):
        verdicts.append(sequence(
            window,
            level(sda_oen=0),
            level(scl_oen=1),
            level(sda_oen=1, scl_oen=1),
            strong=False,
            after_activation=True,
        ))

    for window in sequence_windows("read_sequence"):
        verdicts.append(sequence(
            window,
            level(sda_oen=1, scl_oen=1),
            level(scl_oen=0),
            strong=False,
            after_activation=True,
        ))

    for window in sequence_windows("write_sequence"):
        verdicts.append(sequence(
            window,
            lambda row: out(row, "sda_oen") == inp(row, "din") and out(row, "scl_oen") == 1,
            level(scl_oen=0),
            strong=False,
            after_activation=True,
        ))

    return worst(verdicts)

