def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def probe(row, name):
        return bool(out(row, name))

    def rising_rows(name):
        result = []
        previous = False
        for row in trace:
            current = probe(row, name)
            if current and not previous:
                result.append(row)
            previous = current
        return result

    def groups(name):
        result = []
        current = []
        active = False
        for row in trace:
            now = probe(row, name)
            if now:
                if not active:
                    current = []
                    result.append(current)
                current.append(row)
            active = now
        return result

    def first_row(rows, predicate):
        for row in rows:
            if predicate(row):
                return row
        return None

    failures = []
    evidence = []

    command_probes = (
        ('start_sequence', 'START'),
        ('stop_sequence', 'STOP'),
        ('write_sequence', 'WRITE'),
        ('read_sequence', 'READ'),
    )

    command_groups = []
    for probe_name, label in command_probes:
        for rows in groups(probe_name):
            if rows:
                command_groups.append((rows[0], rows, probe_name, label))
    command_groups.sort(key=lambda item: item[0].get('edge', 0))

    for start_row, rows, probe_name, label in command_groups:
        evidence.append((start_row, label + ' sequence'))

        if label == 'START':
            release = first_row(
                rows,
                lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 1)
            sda_low = first_row(
                rows,
                lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 0)
            scl_low = first_row(rows, lambda r: out(r, 'scl_oen') == 0)
            if release is None or sda_low is None or scl_low is None:
                failures.append((start_row, 'START requires SDA low while SCL is released, followed by SCL being driven low'))

        elif label == 'STOP':
            sda_low = first_row(rows, lambda r: out(r, 'sda_oen') == 0)
            scl_release = first_row(
                rows,
                lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 0)
            sda_release = first_row(
                rows,
                lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 1)
            if sda_low is None or scl_release is None or sda_release is None:
                failures.append((start_row, 'STOP requires SDA low, then released SCL, then released SDA while SCL is released'))

        elif label == 'WRITE':
            expected_sda_oen = 0 if inp(start_row, 'din') == 0 else 1
            data_phase = first_row(rows, lambda r: out(r, 'sda_oen') == expected_sda_oen)
            scl_release = first_row(rows, lambda r: out(r, 'scl_oen') == 1)
            scl_low = first_row(rows, lambda r: out(r, 'scl_oen') == 0)
            if data_phase is None or scl_release is None or scl_low is None:
                failures.append((start_row, 'WRITE requires SDA to represent din, followed by an SCL released phase and a low phase'))

        elif label == 'READ':
            sda_release = first_row(rows, lambda r: out(r, 'sda_oen') == 1)
            scl_release = first_row(rows, lambda r: out(r, 'scl_oen') == 1)
            scl_low = first_row(rows, lambda r: out(r, 'scl_oen') == 0)
            if sda_release is None or scl_release is None or scl_low is None:
                failures.append((start_row, 'READ requires SDA release, an SCL released sample phase, and a subsequent SCL low phase'))

            rises = [r for r in rows if probe(r, 'filtered_scl_rise')]
            if not rises:
                failures.append((start_row, 'READ has no filtered SCL rising-edge sample'))
            else:
                for row in rises:
                    if out(row, 'dout') != out(row, 'ssda'):
                        failures.append((row, 'dout does not capture the synchronized and filtered SDA value at the READ sample'))

        aborted = any(out(row, 'al') == 1 for row in rows)
        ack_rows = [row for row in rows if out(row, 'cmd_ack') == 1]
        if not aborted:
            if not ack_rows:
                failures.append((start_row, label + ' completed without cmd_ack'))
            else:
                for row in ack_rows:
                    if row.get('held') != 1:
                        failures.append((row, 'cmd_ack was not high for exactly one clock'))

    for row in rising_rows('sta_condition'):
        evidence.append((row, 'filtered START detection'))
        if out(row, 'busy') != 1:
            failures.append((row, 'busy did not rise on filtered START detection'))

    for row in rising_rows('sto_condition'):
        evidence.append((row, 'filtered STOP detection'))
        if out(row, 'busy') != 0:
            failures.append((row, 'busy did not clear on filtered STOP detection'))

    wait_rows = [row for row in trace if probe(row, 'slave_wait')]
    if wait_rows:
        evidence.append((wait_rows[0], 'slave clock stretching'))
        for row in wait_rows:
            if out(row, 'scl_oen') != 1:
                failures.append((row, 'SCL was driven low while slave_wait was active'))

    for row in trace:
        sda_loss = probe(row, 'sda_chk') and out(row, 'sda_oen') == 1 and out(row, 'ssda') == 0
        unexpected_stop = probe(row, 'sto_condition') and probe(row, 'active_command') and not probe(row, 'stop_sequence')
        if sda_loss or unexpected_stop:
            evidence.append((row, 'arbitration-loss condition'))
            if out(row, 'al') != 1:
                failures.append((row, 'al did not assert for the declared filtered arbitration-loss condition'))

    if not evidence:
        return (None, None, 'the requirement activation never occurred in this trace')
    if failures:
        row, detail = failures[0]
        return (False, row.get('edge'), detail)
    return (True, None, 'all exercised observable capabilities satisfied')

