def decide(trace):
    completions = []
    failures = []
    saw_incomplete = False

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})

        # A supported command completion is the transition from an active
        # command to idle without arbitration loss.  Reset/abort traces do not
        # constitute completion windows for this routed observation.
        if (prev_out.get('active_command') == 1 and
                out.get('active_command') == 0 and
                out.get('idle') == 1 and
                out.get('al', 0) == 0):
            completions.append(row)
            ack = out.get('cmd_ack')
            if ack != 1:
                failures.append((row['edge'], 'cmd_ack was not asserted at command completion'))
                continue
            if row.get('held', 0) != 1:
                failures.append((row['edge'],
                                 'cmd_ack was asserted for more than one clock interval'))
                continue

            if i + 1 >= len(trace):
                saw_incomplete = True
            else:
                following = trace[i + 1]
                if following.get('outputs', {}).get('cmd_ack') == 1:
                    failures.append((following['edge'],
                                     'cmd_ack remained asserted on the following clock state'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not completions:
        return (None, None, 'no supported command completion occurred in this trace')
    if saw_incomplete:
        return (None, completions[-1]['edge'],
                'cmd_ack was observed at completion, but the following clock state was not present')
    return (True, completions[-1]['edge'],
            'cmd_ack asserted for exactly one clock interval at each observed command completion')

