def decide(trace):
    activations = []

    for i, row in enumerate(trace):
        nreset = row.get('inputs', {}).get('nReset')
        if nreset != 0:
            continue

        previous = None
        if i > 0:
            previous = trace[i - 1].get('inputs', {}).get('nReset')

        # A falling assertion opens the reset window.  If the trace starts
        # while reset is already asserted, the first row is the only available
        # observation of that assertion boundary.
        if i == 0 or previous != 0:
            activations.append(row)

    if not activations:
        return (None, None, 'nReset was never observed asserted low')

