def decide(trace):
    from specflow.refmodel.temporal import after, edges, stable, throughout, worst

    def ena_high(row):
        return row['inputs'].get('ena') == 1

    def ena_low(row):
        return row['inputs'].get('ena') == 0

    def active_command(row):
        return row['outputs'].get('active_command') == 1

    ena_falls = edges(trace, 'ena', 'fall')
    scl_windows = after(
        trace,
        lambda r: r['edge'] in ena_falls
        and ena_low(r)
        and active_command(r),
        until=ena_high,
    )

    scl_verdicts = []
    for window in scl_windows:
        if len(window.rows) < 2:
            scl_verdicts.append(
                (None, window.edge,
                 'no multi-state active-command window while ena was low; '
                 'cannot establish that timed progression was prevented')
            )
        else:
            verdict = stable(window, 'scl_oen')
