    seen_expiry = False
    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        # Timing progression is not owed while reset is active or ena is low.
        enabled = (inputs.get('ena') == 1 and
                   inputs.get('nReset') == 1 and
                   inputs.get('rst') != 1)
        if not enabled:
