        write_active,
        until=lambda row: holds(row, 'cmd_ack', 1),
        aborts=aborted,
    )

    verdicts = []
    for window in windows:
        expected = 0 if window.value('din') == 0 else 1
        verdicts.append(
            eventually(
                window,
                lambda row, value=expected: holds(row, 'sda_oen', value),
                after_activation=True,
                strong=False,
            )
        )

    return worst(verdicts)

