def decide(trace):
    def valid(row):
        return (row['inputs'].get('ena') == 1 and
                row['inputs'].get('nReset') == 1 and
                row['inputs'].get('rst') == 0)

    def qualified(row):
        out = row['outputs']
        return bool(out.get('sta_condition', 0) or out.get('sto_condition', 0))

    failures = []
    exercised = False

    # A qualified filtered START/STOP must produce the corresponding busy level.
    for i, row in enumerate(trace):
        if not valid(row):
            continue
        out = row['outputs']
        is_start = bool(out.get('sta_condition', 0))
        is_stop = bool(out.get('sto_condition', 0))
        if not (is_start or is_stop):
            continue

        target = 1 if is_start else 0
        next_qualified = len(trace)
        for k in range(i + 1, len(trace)):
            if valid(trace[k]) and qualified(trace[k]):
                next_qualified = k
                break

        if i + 1 >= next_qualified:
            continue

        exercised = True
        found = False
        for j in range(i + 1, next_qualified):
            if not valid(trace[j]):
                break
            if trace[j]['outputs'].get('busy') == target:
                found = True
                break

        if not found:
            failures.append((row['edge'],
                             'qualified filtered START/STOP was not reflected on busy'))

    # A raw SCL transition that is not a qualified filtered START/STOP must
    # leave busy unchanged until the next qualified condition.
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if not (valid(prev) and valid(row)):
            continue
        if prev['inputs'].get('scl_i') == row['inputs'].get('scl_i'):
            continue
        if qualified(row):
            continue

        exercised = True
        baseline = prev['outputs'].get('busy')
        for j in range(i, len(trace)):
            if not valid(trace[j]) or qualified(trace[j]):
                break
            if trace[j]['outputs'].get('busy') != baseline:
                failures.append((row['edge'],
                                 'raw SCL transition without a qualified filtered START/STOP changed busy'))
                break

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not exercised:
        return (None, None, 'no enabled SCL transition or qualified filtered START/STOP occurred')
    return (True, None, 'busy responded only to qualified filtered SCL conditions')

def decide(trace):
    # al is a declared output, but REQ-0031 licenses no expectation about it.
    _al_values = [r.get('outputs', {}).get('al') for r in trace]
    return (None, None, 'REQ-0031 does not constrain declared output al; its obligation states no effect on al')

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def enabled(row):
        return row.get('inputs', {}).get('ena') == 1

    def active_released_low(row):
        return (enabled(row)
                and out(row, 'active_command') == 1
                and out(row, 'scl_oen') == 1
                and row.get('inputs', {}).get('scl_i') == 0
                and out(row, 'sscl') == 0)

    def active_released_filtered_high(row):
        return (enabled(row)
                and out(row, 'active_command') == 1
                and out(row, 'scl_oen') == 1
                and out(row, 'sscl') == 1)

    low_rows = [r for r in trace if active_released_low(r)]
    if not low_rows:
        high_rows = [r for r in trace if active_released_filtered_high(r)]
        for r in high_rows:
            if out(r, 'cmd_ack') == 1:
                return (True, r.get('edge'),
                        'cmd_ack occurred with filtered SCL high; no stretching interval was present')
        return (None, None,
                'no enabled active-command interval showed external scl_i low with filtered SCL low')

    for r in low_rows:
        if out(r, 'cmd_ack') == 1:
            return (False, r.get('edge'),
                    'cmd_ack asserted while released SCL was externally low and filtered SCL remained low')

    first_low_index = low_rows[0].get('index', trace.index(low_rows[0]))
    released_high_seen = False
    for r in trace:
        idx = r.get('index', trace.index(r))
        if idx <= first_low_index:
            continue
        if active_released_filtered_high(r):
            released_high_seen = True
        if released_high_seen and out(r, 'cmd_ack') == 1:
            return (True, r.get('edge'),
                    'cmd_ack was withheld during the filtered-low stretch and occurred after filtered SCL became high')

    return (None, None,
            'stretching was observed and cmd_ack was withheld, but no later command completion was observed')

def decide(trace):
    failures = []
    saw_effect = False

    def enabled(row):
        inp = row.get('inputs', {})
        return (inp.get('ena') == 1 and
                inp.get('nReset') == 1 and
                inp.get('rst') == 0)

    def out(row, name):
        return row.get('outputs', {}).get(name)

    # Qualified filtered START/STOP events must be the events that affect busy.
    for row in trace:
        if not enabled(row):
            continue
        if out(row, 'sta_condition'):
            saw_effect = True
            if out(row, 'busy') != 1:
                failures.append((row.get('edge'),
                                 'qualified filtered START did not set busy'))
        if out(row, 'sto_condition'):
            saw_effect = True
            if out(row, 'busy') != 0:
                failures.append((row.get('edge'),
                                 'qualified filtered STOP did not clear busy'))

    # A READ samples the filtered SDA value only at a qualified filtered SCL rise.
    for row in trace:
        if not enabled(row):
            continue
        if out(row, 'read_sequence') and out(row, 'filtered_scl_rise'):
            saw_effect = True
            if out(row, 'dout') != out(row, 'ssda'):
                failures.append((row.get('edge'),
                                 'dout did not capture filtered SDA at the filtered SCL rising edge'))

    # Clock stretching: while the controller is waiting for released SCL to
    # become high, command completion must not be acknowledged.  If the
    # command survives the wait, a later acknowledgement must be observable;
    # an abruptly truncated or aborted attempt remains undecided.
    i = 0
    while i < len(trace):
        row = trace[i]
        if not (enabled(row) and out(row, 'slave_wait')):
            i += 1
            continue

        start = i
        saw_active = False
        while i < len(trace) and enabled(trace[i]) and out(trace[i], 'slave_wait'):
            if out(trace[i], 'active_command'):
                saw_active = True
            if out(trace[i], 'cmd_ack'):
                failures.append((trace[i].get('edge'),
                                 'cmd_ack asserted while filtered SCL was still low in slave_wait'))
            i += 1
        end = i

        if not saw_active:
            continue

        later_ack = False
        aborted = False
        for j in range(end, len(trace)):
            if not enabled(trace[j]):
                break
            if out(trace[j], 'al'):
                aborted = True
                break
            if out(trace[j], 'cmd_ack'):
                later_ack = True
                break
        if later_ack:
            saw_effect = True
        elif not aborted:
            # The wait was exercised, but the trace ended or stopped before a
            # surviving command demonstrated its postponed completion.
            pass

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not saw_effect:
        return (None, None, 'no qualified filtered SCL consequence was exercised')
    return (True, None, 'scl_i consequences were observed only through qualified filtered events')

