def decide(trace):
    def out(row, name):
        return row['outputs'].get(name)

    def enabled(row):
        return row['inputs'].get('ena') == 1 and row['inputs'].get('nReset') != 0 and row['inputs'].get('rst') != 1

    relevant = []
    previous = None

    for row in trace:
        if not enabled(row):
            previous = row
            continue

        sta = out(row, 'sta_condition') == 1
        sto = out(row, 'sto_condition') == 1
        arb_phase = out(row, 'sda_chk') == 1
        filtered_sda = out(row, 'ssda')
        filtered_scl_rise = out(row, 'filtered_scl_rise') == 1
        read_phase = out(row, 'read_sequence') == 1

        if sta or sto:
            relevant.append(row)
            expected_busy = 1 if sta else 0
            if out(row, 'busy') != expected_busy:
                return (False, row['edge'],
                        'busy did not reflect the synchronized and filtered SDA START/STOP event')

        if arb_phase and filtered_sda == 0:
            relevant.append(row)
            if out(row, 'al') != 1:
                return (False, row['edge'],
                        'al did not assert from filtered low SDA during the released-high arbitration-check phase')

        if filtered_scl_rise and read_phase:
            relevant.append(row)
            if out(row, 'dout') != filtered_sda:
                return (False, row['edge'],
                        'dout did not capture the synchronized and filtered SDA value on the filtered SCL rising edge')

        if previous is not None and enabled(previous):
            if out(row, 'busy') != out(previous, 'busy') and not (sta or sto):
                return (False, row['edge'],
                        'busy changed before a synchronized and filtered SDA START/STOP event')
            if out(row, 'al') == 1 and out(previous, 'al') != 1:
                if not (arb_phase and filtered_sda == 0):
                    return (False, row['edge'],
                            'al asserted without filtered low SDA in the released-high arbitration-check phase')
            if out(row, 'dout') != out(previous, 'dout') and read_phase and not filtered_scl_rise:
                return (False, row['edge'],
                        'dout changed without a filtered SCL rising edge during the READ sampling phase')

        previous = row

    if not relevant:
        return (None, None, 'no enabled synchronized/filtered SDA use occurred in this trace')

    return (True, None, 'SDA-dependent status and data uses were qualified by synchronized and filtered events')

def decide(trace):
    def v(row, name):
        return row['outputs'].get(name, row['inputs'].get(name))

    qualifying = []
    for row in trace:
        active = (
            v(row, 'ena') == 1 and
            v(row, 'write_sequence') == 1 and
            v(row, 'sda_chk') == 1 and
            v(row, 'sda_oen') == 1 and
            v(row, 'sto_condition') != 1
        )
        if active:
            qualifying.append(row)

    if not qualifying:
        return (None, None, 'no released-high WRITE arbitration-check phase occurred')

    checked = False
    previous_al = v(trace[0], 'al')
    for row in trace[1:]:
        current_al = v(row, 'al')
        al_rise = previous_al != 1 and current_al == 1
        if al_rise:
            in_phase = (
                v(row, 'ena') == 1 and
                v(row, 'write_sequence') == 1 and
                v(row, 'sda_chk') == 1 and
                v(row, 'sda_oen') == 1 and
                v(row, 'sto_condition') != 1
            )
            if in_phase and v(row, 'ssda') == 1:
                return (False, row['edge'],
                        'al asserted while filtered ssda remained high; raw sda_i was used before synchronization/filtering')
        previous_al = current_al

    for i, row in enumerate(trace):
        in_phase = (
            v(row, 'ena') == 1 and
            v(row, 'write_sequence') == 1 and
            v(row, 'sda_chk') == 1 and
            v(row, 'sda_oen') == 1 and
            v(row, 'sto_condition') != 1
        )
        if not in_phase:
            continue
        if v(row, 'ssda') != 0:
            continue

        checked = True
        for later in trace[i:]:
            later_phase = (
                v(later, 'ena') == 1 and
                v(later, 'write_sequence') == 1 and
                v(later, 'sda_chk') == 1 and
                v(later, 'sda_oen') == 1 and
                v(later, 'sto_condition') != 1
            )
            if not later_phase:
                break
            if v(later, 'al') == 1:
                return (True, later['edge'],
                        'al asserted only after synchronized and filtered ssda became low during SDA arbitration checking')

        return (False, row['edge'],
                'filtered ssda became low during SDA arbitration checking but al did not assert before the phase ended')

    if checked:
        return (True, None, 'arbitration phase completed without an al assertion while filtered ssda remained high')
    return (None, None, 'the arbitration phase occurred but no filtered SDA arbitration condition was observed')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def probe(row, name):
        return bool(out(row, name))

    def enabled(row):
        return inp(row, 'ena') == 1

    relevant = False

    # A raw SDA change which has not reached the filtered SDA value must
    # not directly affect any observable consequence of SDA processing.
    for i in range(1, len(trace)):
        before = trace[i - 1]
        row = trace[i]
        if not enabled(before) or not enabled(row):
            continue
        if inp(before, 'sda_i') == inp(row, 'sda_i'):
            continue
        if out(before, 'ssda') != out(row, 'ssda'):
            continue
        relevant = True
        for port in ('busy', 'al', 'dout'):
            if out(before, port) != out(row, port):
                return (False, row.get('edge'),
                        'raw sda_i changed while filtered ssda was unchanged, '
                        'but %s changed before synchronization/filtering' % port)

    # START and STOP detection must use the filtered SDA transition.
    for i, row in enumerate(trace):
        if not enabled(row):
            continue
        if probe(row, 'sta_condition') or probe(row, 'sto_condition'):
            relevant = True
            expected = 1 if probe(row, 'sta_condition') else 0
            found = False
            for later in trace[i:]:
                if not enabled(later):
                    continue
                if out(later, 'busy') == expected:
                    found = True
                    break
            if not found:
                name = 'START' if expected else 'STOP'
                return (False, row.get('edge'),
                        'filtered %s condition occurred, but busy did not reach %d' %
                        (name, expected))

    # Arbitration is evaluated from filtered SDA during the released-high
    # WRITE checking phase, not from the raw pad input.
    for i, row in enumerate(trace):
        if not enabled(row):
            continue
        if probe(row, 'write_sequence') and probe(row, 'sda_chk'):
            if out(row, 'ssda') == 0:
                relevant = True
                found = False
                for later in trace[i:]:
                    if not enabled(later):
                        continue
                    if out(later, 'al') == 1:
                        found = True
                        break
                if not found:
                    return (False, row.get('edge'),
                            'filtered SDA was low during released-high WRITE arbitration checking, '
                            'but al did not assert')
            elif out(row, 'ssda') == 1 and out(row, 'al') == 0:
                # A raw low value must not cause arbitration loss while the
                # synchronized and filtered value remains high.
                if inp(row, 'sda_i') == 0:
                    relevant = True

    # READ data sampling must use filtered SDA at the filtered SCL rising edge.
    for row in trace:
        if not enabled(row):
            continue
        if probe(row, 'read_sequence') and probe(row, 'filtered_scl_rise'):
            relevant = True
            if out(row, 'dout') != out(row, 'ssda'):
                return (False, row.get('edge'),
                        'dout did not equal synchronized and filtered ssda at the filtered SCL rising edge')

    if not relevant:
        return (None, None, 'the enabled SDA-processing situations did not occur in this trace')
    return (True, None,
            'sda_i effects were observed only through synchronized and filtered SDA situations')

