        return row.get('outputs', {}).get(name)

    def usable(row):
        inputs = row.get('inputs', {})
        return (inputs.get('ena') == 1 and
                inputs.get('nReset') != 0 and
                inputs.get('rst') != 1)

    def rising(i, predicate):
        if not predicate(trace[i]):
            return False
        return i == 0 or not predicate(trace[i - 1])

    def find_level(start, port, expected, stop=None):
        end = len(trace) if stop is None else min(stop, len(trace))
        for j in range(start, end):
