def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def out(row, name):
        return row.get('outputs', {}).get(name, 0)

    def aborted(row):
        return (
            out(row, 'al') == 1
            or row.get('inputs', {}).get('nReset') == 0
            or row.get('inputs', {}).get('rst') == 1
        )

    completions = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        if aborted(current):
            continue
        if any(out(previous, seq) == 1 and out(current, seq) == 0
               for seq in sequence_ports):
            completions.append(i)

    if not completions:
        return (None, None, 'no START, STOP, READ, or WRITE command completion occurred in this trace')

    incomplete = False
    for completion in completions:
        ack_row = None
        for j in range(completion, len(trace)):
            if aborted(trace[j]):
                break
            if out(trace[j], 'cmd_ack') == 1:
                ack_row = j
                break

        if ack_row is None:
            return (
                False,
                trace[completion].get('edge'),
                'cmd_ack was not asserted after the bit-level command finished'
            )

        if ack_row > 0 and out(trace[ack_row - 1], 'cmd_ack') == 1:
            return (
                False,
                trace[ack_row].get('edge'),
                'cmd_ack was already high rather than forming the required completion pulse'
            )

        held_edges = 0
        j = ack_row
        while j < len(trace) and out(trace[j], 'cmd_ack') == 1:
            held_edges += trace[j].get('held', 0)
            if held_edges > 1:
                return (
                    False,
                    trace[ack_row].get('edge'),
                    'cmd_ack was held for more than one clk cycle; expected one cycle'
                )
            j += 1

        if j == len(trace):
            incomplete = True
            continue

        if held_edges != 1:
            return (
                False,
                trace[ack_row].get('edge'),
                'cmd_ack was not asserted for exactly one clk cycle'
            )

    if incomplete:
        return (None, None, 'the trace ended before the cmd_ack pulse duration was fully observed')
    return (True, None, 'cmd_ack was asserted for exactly one clk cycle at every observed command completion')

def decide(trace):
    sequence_names = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def value(row, name):
        return row.get('outputs', {}).get(name, 0)

    def in_sequence(row):
        return any(value(row, name) == 1 for name in sequence_names)

    results = []
    active = False
    aborted = False

    for i, row in enumerate(trace):
        seq = in_sequence(row)
        reset_or_abort = (
            value(row, 'al') == 1 or
            value(row, 'nReset') == 0 or
            value(row, 'rst') == 1
        )

        if seq:
            if not active:
                active = True
                aborted = False
            if reset_or_abort:
                aborted = True
            continue

        if active:
            finishes = value(row, 'idle') == 1
            if finishes and not aborted and not reset_or_abort:
                edge = row.get('edge')
                if value(row, 'cmd_ack') != 1:
                    results.append((False, edge, 'cmd_ack was not asserted when the command finished'))
                elif row.get('held', 0) != 1:
                    results.append((False, edge, 'cmd_ack was not asserted for exactly one clk cycle'))
                else:
                    previous_ack = False
                    if i:
                        previous_ack = value(trace[i - 1], 'cmd_ack') == 1
                    if previous_ack:
                        results.append((False, edge, 'cmd_ack was already high before command completion'))
                    else:
                        pulse_edges = 0
                        pulse_closed = False
                        for following in trace[i:]:
                            if value(following, 'cmd_ack') != 1:
                                pulse_closed = True
                                break
                            pulse_edges += following.get('held', 0)

                        if pulse_edges > 1:
                            results.append((False, edge, 'cmd_ack remained asserted for more than one clk cycle'))
                        elif not pulse_closed:
                            results.append((None, edge, 'the trace ended before the one-cycle cmd_ack pulse was observed to end'))
                        else:
                            results.append((True, edge, 'cmd_ack was high for exactly one clk cycle at command completion'))
            active = False
            aborted = False

    if not results:
        return (None, None, 'no non-aborted START, STOP, READ, or WRITE command completion occurred')

    for result in results:
        if result[0] is False:
            return result
    for result in results:
        if result[0] is None:
            return result
    return (True, results[-1][1], 'cmd_ack was high for exactly one clk cycle at every observed command completion')

def decide(trace):
    sequence_ports = (
        "start_sequence",
        "stop_sequence",
        "read_sequence",
        "write_sequence",
    )
    abort_ports = ("al", "nReset", "rst")
    results = []

    for seq in sequence_ports:
        active = False
        aborted = False

        for i, row in enumerate(trace):
            outputs = row.get("outputs", {})
            seq_now = outputs.get(seq) == 1
            abort_now = any(outputs.get(p) == 1 or row.get("inputs", {}).get(p) == 1
                            for p in abort_ports)

            if not active:
                if seq_now:
                    active = True
                    aborted = abort_now
                continue

            if abort_now:
                aborted = True

            if seq_now:
                continue

            # The sequence has ended.  Reset/arbitration loss means that this
            # command was aborted and no acknowledge was owed.
            if aborted:
                active = False
                aborted = False
                continue

            completion = row
            completion_edge = completion.get("edge")
            if completion.get("outputs", {}).get("cmd_ack") != 1:
                results.append((False, completion_edge,
                                "cmd_ack was not high when %s finished" % seq))
                active = False
                continue

            # Count the contiguous high interval in edges, not rows.  A row
            # may represent more than one clock edge through its `held` field.
            width = 0
            j = i
            ended = False
            while j < len(trace):
                r = trace[j]
                if r.get("outputs", {}).get("cmd_ack") != 1:
                    ended = True
                    break
                width += r.get("held", 1)
                j += 1

            if not ended:
                results.append((None, completion_edge,
                                "cmd_ack pulse for %s reaches the end of the trace; its termination is unobserved" % seq))
            elif width != 1:
                results.append((False, completion_edge,
                                "cmd_ack was high for %d clock edge(s) when %s finished; expected exactly one" % (width, seq)))
            else:
                results.append((True, completion_edge,
                                "cmd_ack was high for exactly one clock edge when %s finished" % seq))

            active = False
            aborted = False

    if not results:
        return (None, None, "no non-aborted START, STOP, READ, or WRITE command finished in this trace")

    for result in results:
        if result[0] is False:
            return result
    for result in results:
        if result[0] is None:
            return result
    return (True, results[-1][1], "every completed non-aborted command acknowledged for exactly one clock edge")

from specflow.refmodel.temporal import TO_END, after, edges, pulse, worst

def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def output_value(row, name):
        return row.get('outputs', {}).get(name, 0)

    def any_condition(conditions):
        def holds(row):
            outputs = row.get('outputs', {})
            inputs = row.get('inputs', {})
            return any(
                all(outputs.get(port, inputs.get(port)) == value
                    for port, value in condition.items())
                for condition in conditions
            )
        return holds

    completion_edges = set()
    for sequence in sequence_ports:
        completion_edges.update(edges(trace, sequence, 'fall'))

    if not completion_edges:
        return (None, None,
                'no START, STOP, READ, or WRITE command completion occurred in this trace')

    windows = after(
        trace,
        lambda row: row.get('edge') in completion_edges,
        until=TO_END,
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1},
        ]),
    )

    follows = False
    return worst([
        pulse(window, 'cmd_ack', width=1, active=1,
              after_activation=follows)
        for window in windows
    ])

def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def value(row, port):
        return row.get('outputs', {}).get(port, 0)

    def aborted(row):
        return (value(row, 'al') == 1 or
                row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    completions = []
    starts = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        for port in sequence_ports:
            if value(previous, port) == 1 and value(current, port) != 1:
                if not aborted(current):
                    completions.append(i)
            if value(previous, port) != 1 and value(current, port) == 1:
                starts.append(i)

    if not completions:
        return (None, None,
                'no non-aborted START, STOP, READ, or WRITE command completion occurred')

    verdicts = []
    for completion in completions:
        next_start = min((i for i in starts if i > completion),
                         default=len(trace))
        rows = trace[completion:next_start]

        episodes = []
        i = 0
        while i < len(rows):
            if value(rows[i], 'cmd_ack') != 1:
                i += 1
                continue
            total_edges = 0
            first = i
            while i < len(rows) and value(rows[i], 'cmd_ack') == 1:
                total_edges += rows[i].get('held', 1)
                i += 1
            episodes.append((first, total_edges))

        if len(episodes) != 1:
            verdicts.append((False, trace[completion].get('edge'),
                             'command completion required exactly one cmd_ack pulse, '
                             f'but this transaction contained {len(episodes)}'))
        elif episodes[0][1] != 1:
            verdicts.append((False, rows[episodes[0][0]].get('edge'),
                             'cmd_ack was asserted for '
                             f'{episodes[0][1]} clock edges; exactly one was required'))
        else:
            verdicts.append((True, rows[episodes[0][0]].get('edge'),
                             'cmd_ack was asserted for exactly one clock edge after command completion'))

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    return (True, None,
            f'{len(verdicts)} non-aborted command completion(s) each had one-clock cmd_ack')

