def decide(trace):
    from specflow.refmodel.temporal import after, worst

    def holds(cond):
        return lambda row: all(row['outputs'].get(port) == value
                               for port, value in cond.items())

    def any_alt(alts):
        predicates = [holds(alt) for alt in alts]
        return lambda row: any(predicate(row) for predicate in predicates)

    starts = holds({'sta_condition': 1})
    stops = any_alt([{'sto_condition': 1}])
    resets = any_alt([{'nReset': 0}, {'rst': 1}])
    windows = after(trace, starts, until=stops, aborts=resets)

    verdicts = []
    for window in windows:
        if not window.closed:
            verdicts.append((None, window.edge,
                             'START occurred but the interval was not completed by STOP'))
            continue

        start_index = None
        for row in trace:
            if row['edge'] == window.edge:
                start_index = row['index']
                break
        if start_index is None:
            verdicts.append((None, window.edge, 'could not locate the START state'))
            continue

        stop_row = None
        for row in trace:
            if row['index'] > start_index and stops(row):
                stop_row = row
                break
        if stop_row is None:
            verdicts.append((None, window.edge,
                             'START occurred but no applicable STOP state was observed'))
            continue

        interval = [row for row in trace
                    if start_index < row['index'] < stop_row['index']]
        high_row = next((row for row in interval
                         if row['outputs'].get('busy') == 1), None)
        if high_row is None:
            verdicts.append((False, stop_row['edge'],
                             'busy never became high after START before STOP'))
            continue

        dropped = next((row for row in interval
                        if row['index'] > high_row['index']
                        and row['outputs'].get('busy') != 1), None)
        if dropped is not None:
            verdicts.append((False, dropped['edge'],
                             'busy cleared before the STOP condition'))
            continue

        if stop_row['outputs'].get('busy') != 0:
            verdicts.append((False, stop_row['edge'],
                             'busy was not cleared on the STOP-detection state'))
            continue

        verdicts.append((True, stop_row['edge'],
                         'busy was set after START, remained set until STOP, and was cleared at STOP'))

    return worst(verdicts)

