def decide(trace):
    samples = []
    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('read_sequence') == 1 and outputs.get('filtered_scl_rise') == 1:
            samples.append(row)

    if not samples:
        return (None, None, 'no filtered SCL rising edge occurred in the READ data-sampling phase')

    for row in samples:
        outputs = row.get('outputs', {})
        received = outputs.get('ssda')
        dout = outputs.get('dout')
        if dout != received:
            return (False, row.get('edge'),
                    f"dout was {dout}, expected the received filtered SDA bit {received} at the filtered SCL rising edge")

    return (True, samples[-1].get('edge'),
            f"dout matched the received filtered SDA bit at {len(samples)} READ sampling event(s)")

def decide(trace):
    events = []
    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('read_sequence') == 1 and outputs.get('filtered_scl_rise') == 1:
            events.append(row)

    if not events:
        return (None, None, 'no READ data-bit sampling event occurred')

