    scl_windows = windows_for('scl_i', scl_changes)
    sda_windows = windows_for('sda_i', sda_changes)

    verdicts = []
    for w in scl_windows:
        expected = w.value('scl_i')
        verdicts.append(
            eventually(
                w,
                lambda row, expected=expected:
                    row['outputs'].get('cscl') == expected,
                strong=True
            )
        )

    for w in sda_windows:
        expected = w.value('sda_i')
        verdicts.append(
            eventually(
                w,
                lambda row, expected=expected:
                    row['outputs'].get('csda') == expected,
                strong=True
            )
        )

    return worst(verdicts)

