def decide(trace):
    scl_history = []
    sda_history = []
    previous_expired = 0
    saw_activation = False
    checked = False

    for row in trace:
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        expired = outputs.get('filter_cnt_expired', 0)
        rising_update = previous_expired == 0 and expired == 1
        previous_expired = expired

        if not rising_update or inputs.get('ena') != 1:
            continue

        saw_activation = True
        if 'cscl' not in outputs or 'csda' not in outputs:
            continue

        scl_history.append(outputs['cscl'])
        sda_history.append(outputs['csda'])
        if len(scl_history) > 3:
            scl_history.pop(0)
        if len(sda_history) > 3:
            sda_history.pop(0)

        if len(scl_history) < 3 or len(sda_history) < 3:
            continue

        checked = True
        expected_scl = 1 if sum(scl_history) >= 2 else 0
        expected_sda = 1 if sum(sda_history) >= 2 else 0
        actual_scl = outputs.get('sscl')
        actual_sda = outputs.get('ssda')

        if actual_scl != expected_scl or actual_sda != expected_sda:
            return (
                False,
                row.get('edge'),
                f"at filter sample update, sscl/ssda were "
                f"{actual_scl}/{actual_sda}, expected majority values "
                f"{expected_scl}/{expected_sda} from the three-sample histories"
            )

    if not saw_activation:
        return (None, None, 'filter sampling activation never occurred')
    if not checked:
        return (None, None, 'fewer than three filter samples were observed; the three-sample histories were not established')
    return (True, None, 'sscl and ssda matched the majority of their respective three-sample histories at every checked filter update')

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after

    def applies(row):
        return (row['inputs'].get('ena') == 1 and
                row['outputs'].get('filter_cnt_expired') == 1)

    windows = after(trace, applies, until=WHILE_ACTIVE)
    if not windows:
        return (None, None, 'no enabled filter-sample update occurred')

    scl_samples = []
    sda_samples = []
    checked = False

