            return (False, row.get('edge'),
                    'the filtered outputs are not the majority of the respective three-sample histories')

    if not checked:
        return (None, windows[-1].edge,
                'fewer than three filter samples occurred; no complete three-sample history was exercised')

    return (True, None,
            'sscl and ssda matched the majority of their respective three-sample histories')

