def decide(trace):
    history_scl = []
    history_sda = []
    updates = []
    previous_expired = 0

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        expired = outputs.get('filter_cnt_expired', 0)

        # A filter sample update is an action, so recognize its rising
        # transition rather than treating a held probe level as many updates.
        update = (
            inputs.get('ena') == 1 and
            expired == 1 and
            previous_expired == 0
        )
        previous_expired = expired

        if not update:
            continue

        if 'fscl' not in outputs or 'fsda' not in outputs:
            continue

        history_scl.append(outputs['fscl'])
        history_sda.append(outputs['fsda'])
        if len(history_scl) > 3:
            history_scl.pop(0)
        if len(history_sda) > 3:
            history_sda.pop(0)

        if len(history_scl) == 3 and len(history_sda) == 3:
            expected_scl = 1 if sum(history_scl) >= 2 else 0
            expected_sda = 1 if sum(history_sda) >= 2 else 0
            updates.append((i, expected_scl, expected_sda))

    if not updates:
        return (None, None, 'filter sample update activation never occurred or three samples were not observed')

    for n, (start, expected_scl, expected_sda) in enumerate(updates):
        end = updates[n + 1][0] if n + 1 < len(updates) else len(trace)
        matched = False

        for row in trace[start:end]:
            outputs = row.get('outputs', {})
            if (
                outputs.get('sscl') == expected_scl and
                outputs.get('ssda') == expected_sda
            ):
                matched = True
                break

        if not matched and n + 1 < len(updates):
            edge = trace[updates[n + 1][0]].get('edge')
            return (
                False,
                edge,
                f"after a filter sample update, sscl/ssda did not reach "
                f"the majority values {expected_scl}/{expected_sda} of the "
                f"three-sample fscl/fsda histories before the next update"
            )

        if not matched:
            return (
                None,
                None,
                'the final filter-sample window ended before the majority result was observable'
            )

    return (
        True,
        None,
        'sscl and ssda reached the majority values of their respective three-sample fscl/fsda histories for every observed filter sample update'
    )

