def decide(trace):
    cases = (("scl_i", "sscl"), ("sda_i", "ssda"))
    witnessed = False

    for input_port, filtered_port in cases:
        for i in range(1, len(trace)):
            before = trace[i - 1]["inputs"].get(input_port)
            current = trace[i]["inputs"].get(input_port)
            if current == before:
                continue

            baseline = trace[i - 1]["outputs"].get(filtered_port)
            return_index = None
            for j in range(i + 1, len(trace)):
                if trace[j]["inputs"].get(input_port) == before:
                    return_index = j
                    break

            if return_index is None:
                continue

            witnessed = True
            for j in range(i, return_index + 1):
                value = trace[j]["outputs"].get(filtered_port)
                if value != baseline:
                    return (
                        False,
                        trace[j]["edge"],
                        f"{input_port} glitch changed {filtered_port} from {baseline} to {value}"
                    )

    if not witnessed:
        return (None, None, "no completed short input excursion occurred in this trace")

    return (True, None, "completed input excursions did not change the corresponding filtered outputs")

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def held_edges(row):
        return row.get('held', 1)

    failures = []
    exercised = False

    # A short glitch is a transient excursion which affects at most one
    # filter sample, while the preceding two sampled values were stable.
    for port, filtered in (("scl_i", "sscl"), ("sda_i", "ssda")):
        samples = []
        for i, row in enumerate(trace):
            if out(row, "filter_cnt_expired"):
                samples.append((i, row["inputs"].get(port)))

        for i in range(1, len(trace)):
            before = trace[i - 1]["inputs"].get(port)
            changed = trace[i]["inputs"].get(port)
            if changed == before:
                continue

            end = None
            for j in range(i + 1, len(trace)):
                if trace[j]["inputs"].get(port) == before:
                    end = j
                    break
            if end is None:
                continue

            prior = [v for k, v in samples if k < i]
            differing = [v for k, v in samples if i <= k <= end and v != before]
            if len(prior) < 2 or prior[-1] != before or prior[-2] != before:
                continue
            if len(differing) > 1:
                continue

            exercised = True
            for k in range(i, end + 1):
                if out(trace[k], filtered) != out(trace[i - 1], filtered):
                    failures.append((trace[k].get("edge"), port, filtered))
                    break

    if failures:
        edge, port, filtered = failures[0]
        return (False, edge, f"short {port} glitch changed filtered {filtered}")
    if not exercised:
        return (None, None, "no short glitch with a stable preceding history and at most one differing filter sample")
    return (True, None, "short glitches did not change the corresponding three-sample majority-filtered value")

def decide(trace):
    cases = (("scl_i", "sscl"), ("sda_i", "ssda"))
    witnessed = False

    def out(row, name):
        return row.get("outputs", {}).get(name)

    def normal_idle(row):
        return (row.get("inputs", {}).get("nReset") == 1
                and row.get("inputs", {}).get("rst") == 0
                and row.get("inputs", {}).get("ena") == 1
                and out(row, "idle") == 1
                and out(row, "active_command") == 0)

    for input_port, filtered_port in cases:
        for i in range(1, len(trace)):
            before = trace[i - 1].get("inputs", {}).get(input_port)
            current = trace[i].get("inputs", {}).get(input_port)
            if before == current or not normal_idle(trace[i]):
                continue

            return_index = None
            abandoned = False
            for j in range(i + 1, len(trace)):
                row = trace[j]
                if (row.get("inputs", {}).get("nReset") != 1
                        or row.get("inputs", {}).get("rst") != 0):
                    abandoned = True
                    break
                if out(row, "active_command") == 1:
                    abandoned = True
                    break
                if row.get("inputs", {}).get(input_port) == before:
                    return_index = j
                    break

            if abandoned or return_index is None:
                continue

            witnessed = True
            baseline = out(trace[i - 1], filtered_port)
            for j in range(return_index, len(trace)):
                row = trace[j]
                if (row.get("inputs", {}).get("nReset") != 1
                        or row.get("inputs", {}).get("rst") != 0
                        or out(row, "active_command") == 1):
                    break
                if out(row, filtered_port) == baseline:
                    break
            else:
                return (
                    False,
                    trace[return_index]["edge"],
                    f"short {input_port} excursion did not recover {filtered_port} "
                    f"to its pre-glitch value {baseline}"
                )

    if not witnessed:
