def decide(trace):
    cases = (("scl_i", "sscl"), ("sda_i", "ssda"))
    witnessed = False

    def value(row, section, name):
        return row.get(section, {}).get(name)

    def reset_active(row):
        return (value(row, "inputs", "nReset") != 1
                or value(row, "inputs", "rst") == 1)

    failures = []

    for input_port, filtered_port in cases:
        for i in range(1, len(trace)):
            before = value(trace[i - 1], "inputs", input_port)
            changed = value(trace[i], "inputs", input_port)
            if before is None or changed is None or changed == before:
                continue
            if reset_active(trace[i - 1]) or reset_active(trace[i]):
                continue

            return_index = None
            abandoned = False
            for j in range(i + 1, len(trace)):
                if reset_active(trace[j]):
                    abandoned = True
                    break
                if value(trace[j], "inputs", input_port) == before:
                    return_index = j
                    break

            if abandoned:
                continue
            if return_index is None:
                continue

            witnessed = True
            baseline = value(trace[i - 1], "outputs", filtered_port)
            if baseline is None:
                continue

            for j in range(i, return_index + 1):
                observed = value(trace[j], "outputs", filtered_port)
                if observed != baseline:
                    failures.append(
                        (trace[j].get("edge"),
                         f"short {input_port} excursion changed {filtered_port} "
                         f"from its pre-glitch value {baseline}"))
                    break

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not witnessed:
        return (None, None, "no completed short glitch was observed on scl_i or sda_i")
    return (True, None, "completed short input excursions did not alter the corresponding filtered value")

def decide(trace):
    cases = (("scl_i", "sscl"), ("sda_i", "ssda"))

    def v(row, section, name):
        return row.get(section, {}).get(name)

    def reset_active(row):
        return v(row, "inputs", "nReset") != 1 or v(row, "inputs", "rst") == 1

    def idle(row):
        return v(row, "outputs", "idle") == 1

    witnessed = False

    for input_port, filtered_port in cases:
        for i in range(1, len(trace)):
            before = v(trace[i - 1], "inputs", input_port)
            now = v(trace[i], "inputs", input_port)
            if before is None or now is None or now == before:
                continue
            if reset_active(trace[i - 1]) or reset_active(trace[i]):
                continue
            if not idle(trace[i - 1]) or not idle(trace[i]):
                continue

            end = None
            for j in range(i + 1, len(trace)):
                if reset_active(trace[j]):
                    break
                if v(trace[j], "inputs", input_port) == before:
                    if idle(trace[j]):
                        end = j
                    break
            if end is None:
                continue

            sample_edges = sum(
                r.get("held", 1)
                for r in trace[i:end + 1]
                if v(r, "outputs", "filter_cnt_expired") == 1
            )
            if sample_edges >= 3:
                continue

            baseline = v(trace[i - 1], "outputs", filtered_port)
            if baseline is None:
                continue
            witnessed = True

            for j in range(i, end + 1):
                observed = v(trace[j], "outputs", filtered_port)
                if observed != baseline:
                    return (
                        False,
                        trace[j].get("edge"),
                        f"short idle {input_port} glitch changed {filtered_port}; "
                        "the requirement says short glitches are reduced by the three-sample majority filter"
                    )

    if not witnessed:
        return (None, None, "no completed idle input excursion shorter than three filter samples was observed")
    return (
        True,
        None,
        "completed idle excursions shorter than three filter samples did not change the corresponding filtered output"
    )

