def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst

    def input_holds(cond):
        return lambda row: all(row['inputs'].get(port) == value
                               for port, value in cond.items())

    def output_holds(cond):
        return lambda row: all(row['outputs'].get(port) == value
                               for port, value in cond.items())

    start = lambda row: (
        input_holds({'scl_i': 1, 'sda_i': 0})(row)
        and output_holds({'sta_condition': 1})(row)
    )
    stop = output_holds({'sto_condition': 1})
    reset = lambda row: row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    windows = after(trace, start, until=stop, aborts=reset)
    return worst([
        throughout(
            window,
            lambda row: row['outputs'].get('busy') == 1,
            after_activation=True
        )
        for window in windows
    ])

