    def output_is(port, value):
        return lambda row: row['outputs'].get(port) == value

    def reset_active(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    # The requirement names the filtered START/STOP situations.  These
    # declared probes are the narrow trigger and closing condition.
    windows = after(
        trace,
        output_is('sta_condition', 1),
        until=output_is('sto_condition', 1),
        aborts=reset_active
    )

    verdicts = []
    for window in windows:
        rows = window.rows
        start_edge = window.edge

        # Allow the registered busy output to reach its required level without
        # choosing an otherwise unspecified distinct-state latency.  The
        # activation row is included so an already-set status is also valid.
        busy_at = None
        for pos, row in enumerate(rows):
            if row['outputs'].get('sto_condition') == 1:
                break
            if row['outputs'].get('busy') == 1:
                busy_at = pos
                break

        if busy_at is None:
            if window.closed:
                verdicts.append((False, start_edge,
                                 'busy never became high after the filtered START condition'))
            else:
                verdicts.append((None, None,
                                 'filtered START occurred but the trace ended before busy was observed'))
            continue

        bad = None
        stop_seen = False
        for row in rows[busy_at:]:
            if row['outputs'].get('sto_condition') == 1:
                stop_seen = True
                break
            if row['outputs'].get('busy') != 1:
                bad = row
                break

        if bad is not None:
            verdicts.append((False, bad['edge'],
                             'busy fell before the filtered STOP condition'))
        elif not window.closed or not stop_seen:
            verdicts.append((None, None,
                             'busy was high, but the filtered STOP transaction was not completed in the trace'))
        else:
            verdicts.append((True, None,
                             'busy became high for the filtered START transaction and remained high until STOP'))

    return worst(verdicts)

