    from specflow.refmodel.temporal import TO_END, after

    def active(row):
        return row['outputs'].get('active_command') == 1

    def inactive(row):
        return row['outputs'].get('active_command') != 1

    def reset(row):
        inputs = row['inputs']
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    windows = after(trace, active, until=inactive, aborts=reset)
    saw_stop = False

    for window in windows:
        rows = window.rows
        if any(reset(row) for row in rows):
            continue

        for i, row in enumerate(rows):
            outputs = row['outputs']
            if (outputs.get('sto_condition') != 1
                    or outputs.get('active_command') != 1
                    or outputs.get('stop_sequence') == 1):
                continue

            saw_stop = True
            if outputs.get('al') == 1:
                return (False, row['edge'],
                        'al was already high at the filtered STOP event; it did not newly assert for the non-STOP command')

            for later in rows[i + 1:]:
                if later['outputs'].get('al') == 1:
                    return (True, later['edge'],
                            'al asserted after a filtered STOP during an active non-STOP command')

            return (False, row['edge'],
                    'filtered STOP occurred during an active non-STOP command, but al did not assert')

    if not saw_stop:
        return (None, None,
                'no filtered STOP was detected during an active non-STOP command')

    return (None, None, 'the qualifying STOP window was aborted before a verdict')

