        return (
            row['inputs'].get('ena') == 1
            and row['inputs'].get('cmd') in non_stop
            and row['outputs'].get('active_command') == 1
        )

    def ends_active(row):
        return (
            row['outputs'].get('active_command') != 1
            or row['outputs'].get('al') == 1
        )

    def reset(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    al_rises = edges(trace, 'al', 'rise')
    windows = after(
        trace,
        active_non_stop,
        until=ends_active,
        aborts=reset,
    )

    verdicts = []
    for window in windows:
        rows = window.rows
        if not rows or any(reset(row) for row in rows):
            verdicts.append((None, window.edge, 'active non-STOP command was aborted by reset'))
            continue

        stops = [row for row in rows if row['outputs'].get('sto_condition') == 1]
        if not stops:
            verdicts.append((None, None, 'no filtered STOP condition occurred during the active non-STOP command'))
            continue

        stop = stops[0]
        stop_index = stop['index']
        rises_after_stop = [edge for edge in al_rises if edge > stop['edge']]
        if rises_after_stop:
            verdicts.append((True, rises_after_stop[0], 'al newly asserted after the active non-STOP STOP condition'))
        else:
            verdicts.append((False, stop['edge'], 'filtered STOP occurred while active on a non-STOP command, but al did not newly assert'))

    return worst(verdicts)

