def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def holds(cond):
        def predicate(row):
            for port, value in cond.items():
                values = row.get('outputs', {})
                if port not in values:
                    values = row.get('inputs', {})
                if values.get(port) != value:
                    return False
            return True
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])
    until_ack = any_condition([{'cmd_ack': 1}])

    commands = [
        (1, 'start_sequence', 'START'),
        (2, 'stop_sequence', 'STOP'),
        (8, 'read_sequence', 'READ'),
        (4, 'write_sequence', 'WRITE'),
    ]
    verdicts = []
    for cmd_value, sequence_probe, name in commands:
        applies = lambda row, value=cmd_value: (
            row.get('inputs', {}).get('cmd') == value
            and row.get('inputs', {}).get('ena') == 1
            and row.get('outputs', {}).get('clk_en') == 1
            and row.get('outputs', {}).get('idle') == 1
        )
        windows = after(
            trace,
            applies,
            until=until_ack,
            aborts=aborts,
        )
        verdicts.extend(
            eventually(
                window,
                lambda row, probe=sequence_probe: row.get('outputs', {}).get(probe) == 1,
                strong=True,
                after_activation=True,
            )
            for window in windows
        )
    return worst(verdicts)

