            for port, value in cond.items():
                actual = row['outputs'].get(port, row['inputs'].get(port))
                if actual != value:
                    return False
            return True
        return predicate

    def any_value(port, values, fixed=None):
        fixed = fixed or {}
        def predicate(row):
            if any(row['inputs'].get(k) != v for k, v in fixed.items()):
                return False
            return row['inputs'].get(port) in values
        return predicate

    aborts = lambda row: (
        row['outputs'].get('al') == 1 or
        row['inputs'].get('nReset') == 0 or
        row['inputs'].get('rst') == 1
    )

    def aborted(row):
        return aborts(row)

    def command_window(value):
        applies = lambda row: (
            row['inputs'].get('cmd') == value and
            row['inputs'].get('ena') == 1 and
            row['outputs'].get('clk_en') == 1 and
            row['outputs'].get('idle') == 1
        )
        return after(
            trace,
            applies,
            until=holds({'cmd_ack': 1}),
            aborts=aborted
        )

    checks = []
    for value, sequence in (
        (1, 'start_sequence'),
        (2, 'stop_sequence'),
        (4, 'write_sequence'),
        (8, 'read_sequence'),
    ):
        windows = command_window(value)
        checks.extend(
            eventually(
                window,
