                strong=True,
                after_activation=True
            )
            for window in windows
        )

    return worst(checks)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def holds(cond):
        def predicate(row):
            outputs = row.get('outputs', {})
            inputs = row.get('inputs', {})
            return all(
                outputs.get(port, inputs.get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def any_value(port, values):
        return lambda row: row.get('inputs', {}).get(port) in values

    aborts = lambda row: (
        row.get('outputs', {}).get('al') == 1
        or row.get('inputs', {}).get('nReset') == 0
        or row.get('inputs', {}).get('rst') == 1
    )

    applies = lambda row: (
        any_value('cmd', (1, 2, 8, 4))(row)
        and row.get('inputs', {}).get('ena') == 1
        and row.get('outputs', {}).get('clk_en') == 1
        and row.get('outputs', {}).get('idle') == 1
    )

    windows = after(
        trace,
        applies,
        until=TO_END,
        aborts=aborts,
    )

    def enters_corresponding_sequence(window):
        command = window.value('cmd')
        sequence_probe = {
            1: 'start_sequence',
            2: 'stop_sequence',
            8: 'read_sequence',
            4: 'write_sequence',
        }.get(command)
        if sequence_probe is None:
            return (None, None, 'unsupported command is outside this obligation')
        return eventually(
            window,
            lambda row: row.get('outputs', {}).get(sequence_probe) == 1,
            strong=False,
            after_activation=True,
        )

    return worst([enters_corresponding_sequence(window) for window in windows])

