from specflow.refmodel.temporal import TO_END, after, sequence, throughout, worst


def decide(trace):
    def held(port, value):
        return lambda r: r['outputs'].get(port) == value

    def phase(**values):
        return lambda r: all(r['outputs'].get(k) == v for k, v in values.items())

    def any_probe(row):
        return any(row['outputs'].get(p) == 1 for p in (
            'start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence'))

    def aborts(row):
        return (row['outputs'].get('al') == 1 or
                row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    windows = after(
        trace,
        any_probe,
        until=lambda r: r['outputs'].get('cmd_ack') == 1,
        aborts=aborts,
    )

    verdicts = []
    for w in windows:
        is_start = w.value('start_sequence') == 1
        is_stop = w.value('stop_sequence') == 1
        is_read = w.value('read_sequence') == 1
        is_write = w.value('write_sequence') == 1

        if is_start:
            verdicts.append(
                sequence(
                    w,
                    phase(scl_oen=1, sda_oen=0),
                    phase(scl_oen=0, sda_oen=0),
                    strong=True,
                    after_activation=True,
                )
            )
            verdicts.append(
                throughout(
                    w,
                    lambda r: r['outputs'].get('sda_chk') == 0,
                    after_activation=True,
                )
            )
        elif is_stop:
            verdicts.append(
                sequence(
                    w,
                    phase(scl_oen=1, sda_oen=0),
                    phase(scl_oen=1, sda_oen=1),
                    strong=True,
                    after_activation=True,
                )
            )
            verdicts.append(
                throughout(
                    w,
                    lambda r: r['outputs'].get('sda_chk') == 0,
                    after_activation=True,
                )
            )
        elif is_read:
            verdicts.append(
                sequence(
                    w,
                    phase(scl_oen=1, sda_oen=1),
                    phase(scl_oen=0, sda_oen=1),
                    strong=True,
                    after_activation=True,
                )
            )
            verdicts.append(
                throughout(
                    w,
                    lambda r: r['outputs'].get('sda_chk') == 0,
                    after_activation=True,
                )
            )
        elif is_write:
            expected_sda = 0 if w.value('din') == 0 else 1
            verdicts.append(
                sequence(
                    w,
                    phase(scl_oen=1, sda_oen=expected_sda, sda_chk=1),
                    phase(scl_oen=0, sda_oen=expected_sda),
                    strong=True,
                    after_activation=True,
                )
            )

    return worst(verdicts)

