    def any_condition(conditions):
        def predicate(row):
            return any(
                all(row['outputs'].get(name, row['inputs'].get(name)) == value
                    for name, value in condition.items())
                for condition in conditions
            )
        return predicate

    def phase(**values):
        return lambda row: all(row['outputs'].get(name) == value
                               for name, value in values.items())

    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    verdicts = []
    sequence_names = [
        'start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence'
    ]

    for name in sequence_names:
        rising = edges(trace, name, 'rise')
        windows = after(
            trace,
            lambda row, rising=rising: row['edge'] in rising,
            until=phase(cmd_ack=1),
            aborts=aborts,
        )

        for window in windows:
            if name == 'start_sequence':
                # SDA is pulled low while SCL is released, then SCL is driven low.
                verdicts.append(sequence(
                    window,
                    phase(scl_oen=1, sda_oen=0, sda_chk=0),
                    phase(scl_oen=0, sda_chk=0),
                    strong=True,
                    after_activation=True,
                ))
            elif name == 'stop_sequence':
                # SDA is low, SCL is released, then SDA is released while SCL is high.
                verdicts.append(sequence(
                    window,
                    phase(scl_oen=0, sda_oen=0, sda_chk=0),
                    phase(scl_oen=1, sda_oen=0, sda_chk=0),
                    phase(scl_oen=1, sda_oen=1, sda_chk=0),
                    strong=True,
                    after_activation=True,
                ))
            elif name == 'read_sequence':
                # SDA is released and SCL is released for sampling, then SCL is low.
                verdicts.append(sequence(
                    window,
                    phase(sda_oen=1, scl_oen=1, sda_chk=0),
                    phase(sda_oen=1, scl_oen=0, sda_chk=0),
                    strong=True,
                    after_activation=True,
                ))
            else:
                # WRITE drives/releases SDA from din, releases SCL with arbitration
                # checking enabled, then drives SCL low and disables the check.
                data_oen = 0 if window.value('din') == 0 else 1
                verdicts.append(sequence(
                    window,
                    phase(scl_oen=0, sda_oen=data_oen, sda_chk=0),
                    phase(scl_oen=1, sda_oen=data_oen, sda_chk=1),
                    phase(scl_oen=0, sda_oen=data_oen, sda_chk=0),
