            outputs.get('start_sequence', 0)
            or outputs.get('stop_sequence', 0)
            or outputs.get('read_sequence', 0)
            or outputs.get('write_sequence', 0)
        )

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    def arbitration_lost(row):
        return row.get('outputs', {}).get('al') == 1

    verdicts = []
