from specflow.refmodel.temporal import after, eventually, worst


def decide(trace):
    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_alternative(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    activation = lambda row: (
        row['inputs'].get('cmd') == 4
        and row['inputs'].get('ena') == 1
        and row['outputs'].get('write_sequence') == 1
    )
    closes = any_alternative([{'scl_oen': 0}])
    aborts = any_alternative([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(trace, activation, until=closes, aborts=aborts)
    follows = True
    verdicts = []

    for window in windows:
        required_sda_oen = window.value('din')
        high_phase = lambda row: (
            row['outputs'].get('scl_oen') == 1
            and row['outputs'].get('sda_oen') == required_sda_oen
            and row['outputs'].get('sda_chk') == 1
        )
        verdict = eventually(
            window,
            high_phase,
            strong=True,
            after_activation=follows,
        )
        if verdict[0] is True and not window.closed:
            verdicts.append((
                False,
                verdict[1],
                'WRITE obligation was not completed: after the SCL-high phase, the sequence did not pull scl_oen low'
            ))
        else:
            verdicts.append(verdict)

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def value(row, port):
        if port in row.get('outputs', {}):
            return row['outputs'][port]
        return row.get('inputs', {}).get(port)

    def holds(row, conditions):
        return all(value(row, port) == expected
                   for port, expected in conditions.items())

    def any_condition(conditions):
        return lambda row: any(holds(row, condition) for condition in conditions)

    applies = lambda row: (
        value(row, 'ena') == 1 and
        value(row, 'write_sequence') == 1
    )
    closes = lambda row: value(row, 'scl_oen') == 0
    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(trace, applies, until=closes, aborts=aborts)

    def decision(window):
        expected_sda_oen = window.value('din')
        high_phase = lambda row: (
            value(row, 'scl_oen') == 1 and
            value(row, 'sda_oen') == expected_sda_oen and
            value(row, 'sda_chk') == 1
        )

        high_result = eventually(
            window,
            high_phase,
            strong=True,
            after_activation=True,
        )
        if high_result[0] is not True:
            return high_result

        high_rows = [row for row in window.rows if high_phase(row)]
        if not high_rows:
            return (False, window.edge,
                    'the WRITE SCL-high phase was not observed')
        high_index = high_rows[0]['index']

        low_rows = [
            row for row in trace
            if row['index'] > high_index and value(row, 'scl_oen') == 0
        ]
        if low_rows:
            low = low_rows[0]
            return (True, low['edge'],
                    'WRITE phase had sda_oen equal to din and sda_chk asserted during released SCL high, then scl_oen was driven low')

        start_index = min(
            (row['index'] for row in trace if row['edge'] == window.edge),
            default=high_index,
        )
        aborted = [
            row for row in trace
            if row['index'] >= start_index and aborts(row)
        ]
        if aborted:
            return (None, None, 'WRITE transaction was aborted by reset or arbitration loss')
        return (False, high_rows[0]['edge'],
                'WRITE SCL-high phase occurred but the sequence never pulled scl_oen low')

    return worst([decision(window) for window in windows])

