def decide(trace):
    activated = []
    expected = {
        'scl_oen': 1,
        'sda_oen': 1,
        'cmd_ack': 0,
        'al': 0,
        'busy': 0,
        'idle': 1,
        'filter_cnt': 0,
        'fscl': 1,
        'fsda': 1,
        'sscl': 1,
        'ssda': 1,
    }

    for row in trace:
        inputs = row.get('inputs', {})
        if inputs.get('nReset') != 0 and inputs.get('rst') != 1:
            continue

        activated.append(row)
        outputs = row.get('outputs', {})
        bad = [
            (port, value, expected[port])
            for port, value in expected.items()
            if outputs.get(port) != expected[port]
        ]
        if bad:
            port, actual, wanted = bad[0]
            return (
                False,
                row.get('edge'),
                f"reset asserted but {port} was {actual!r}, expected {wanted!r}"
            )

    if not activated:
        return (None, None, 'no asynchronous or synchronous reset assertion occurred')

    return (
        True,
        activated[-1].get('edge'),
        'all observed reset states returned the FSM and declared reset observables to their specified values'
    )

def decide(trace):
    expected = {
        'scl_oen': 1,
        'sda_oen': 1,
        'cmd_ack': 0,
        'al': 0,
        'busy': 0,
        'idle': 1,
        'filter_cnt': 0,
        'fscl': 1,
        'fsda': 1,
        'sscl': 1,
        'ssda': 1,
    }

    checks = []

    def check_row(row):
        outputs = row.get('outputs', {})
        for port, wanted in expected.items():
            actual = outputs.get(port)
            if actual != wanted:
                return (
                    False,
                    row.get('edge'),
                    f"reset asserted but {port} was {actual!r}, expected {wanted!r}"
                )
        return None

    for i in range(1, len(trace)):
        previous = trace[i - 1].get('inputs', {})
        current = trace[i].get('inputs', {})

        async_asserted = (
            previous.get('nReset') != 0 and current.get('nReset') == 0
        )
        sync_asserted = (
            previous.get('rst') != 1 and current.get('rst') == 1
        )

        if async_asserted:
            j = i
            while j < len(trace) and trace[j].get('inputs', {}).get('nReset') == 0:
                checks.append(check_row(trace[j]))
                j += 1

        if sync_asserted:
            j = i + 1
            if j < len(trace):
                while j < len(trace) and trace[j].get('inputs', {}).get('rst') == 1:
                    checks.append(check_row(trace[j]))
                    j += 1

    for result in checks:
        if result is not None and result[0] is False:
            return result

    if not checks:
        return (None, None, 'no asynchronous nReset assertion or synchronous rst assertion was observed')

    last_edge = None
    for row in trace:
        inputs = row.get('inputs', {})
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            last_edge = row.get('edge')

    return (
        True,
        last_edge,
        'all observed reset operations established idle, released enables, cleared status, and reset filter observables'
    )

