def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    def any_condition(conditions):
        def predicate(row):
            return any(
                all(row['inputs'].get(port) == value for port, value in condition.items())
                for condition in conditions
            )
        return predicate

    aborts = any_condition([
        {'nReset': 0},
        {'rst': 1},
    ])

    verdicts = []
    for input_port, sampled_port in [('scl_i', 'cscl'), ('sda_i', 'csda')]:
        changed = edges(trace, input_port, 'change')
        windows = after(
            trace,
            lambda row, changed=changed: (
                row['edge'] in changed
                and row['inputs'].get('nReset') == 1
                and row['inputs'].get('rst') == 0
            ),
            overlap=True,
            until=TO_END,
            aborts=aborts,
        )
        verdicts.extend([
            eventually(
                window,
                lambda row, sampled_port=sampled_port, window=window: (
                    row['outputs'].get(sampled_port) == window.value(input_port)
                ),
                strong=True,
                after_activation=True,
            )
            for window in windows
        ])

    return worst(verdicts)

from specflow.refmodel.temporal import TO_END, after

def decide(trace):
    def active(row):
        return row['inputs'].get('nReset') == 1 and row['inputs'].get('rst') == 0

    windows = after(
        trace,
        active,
        until=TO_END,
        aborts=lambda r: r['inputs'].get('nReset') == 0 or r['inputs'].get('rst') == 1
    )
    if not windows:
        return (None, None, 'reset-deasserted sampling window never occurred')

    saw_evidence = False
    for window in windows:
        rows = [
            r for r in window.rows
            if r['inputs'].get('nReset') == 1 and r['inputs'].get('rst') == 0
        ]
        if not rows:
            continue

        for inp, probe in (('scl_i', 'cscl'), ('sda_i', 'csda')):
            starts = []
            for i, row in enumerate(rows):
                value = row['inputs'].get(inp)
                if i == 0 or value != rows[i - 1]['inputs'].get(inp):
                    starts.append(i)

            for k, start in enumerate(starts):
                target = rows[start]['inputs'].get(inp)
                end = starts[k + 1] if k + 1 < len(starts) else len(rows)
                matched = any(
                    rows[j]['outputs'].get(probe) == target
                    for j in range(start, end)
                )
                if matched:
                    saw_evidence = True
                elif k + 1 < len(starts):
                    return (
                        False,
                        rows[start]['edge'],
                        f'{probe} never sampled {inp}={target} before {inp} changed'
                    )

    if not saw_evidence:
        return (None, None, 'no completed input interval provided observable sampling evidence')
    return (True, None, 'cscl and csda sampled observed scl_i and sda_i values with unspecified synchronizer latency')

