def decide(trace):
    opportunities = []
    if not trace:
        return (None, None, 'no raw bus-signal presentation was observed')

    # Check the initial presented values and every later raw-signal change.
    previous = None
    for i, row in enumerate(trace):
        raw = (row['inputs'].get('scl_i'), row['inputs'].get('sda_i'))
        if previous is None or raw != previous:
            opportunities.append((i, raw))
        previous = raw

    if not opportunities:
        return (None, None, 'no raw scl_i or sda_i capture opportunity occurred')

    for i, expected in opportunities:
        found_scl = False
        found_sda = False
        for row in trace[i:]:
            outputs = row['outputs']
            if outputs.get('cscl') == expected[0]:
                found_scl = True
            if outputs.get('csda') == expected[1]:
                found_sda = True
            if found_scl and found_sda:
                break

        if not found_scl or not found_sda:
            missing = []
            if not found_scl:
                missing.append('cscl')
            if not found_sda:
                missing.append('csda')
            return (False, trace[i]['edge'],
                    f"raw scl_i/sda_i value {expected!r} was not eventually reflected in "
                    f"capture probe(s): {', '.join(missing)}")

    return (True, None,
            'each observed raw scl_i/sda_i presentation was eventually reflected by cscl/csda')

def decide(trace):
    opportunities = []
    previous = None
    in_reset = True

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        reset = inputs.get('nReset') == 0 or inputs.get('rst') == 1
        if reset:
            in_reset = True
            previous = None
            continue

        raw = (inputs.get('scl_i'), inputs.get('sda_i'))
        if raw[0] is None or raw[1] is None:
            continue
        if in_reset or raw != previous:
            opportunities.append((i, raw))
        previous = raw
        in_reset = False

    if not opportunities:
        return (None, None, 'no post-reset raw scl_i/sda_i capture presentation occurred')

    for i, expected in opportunities:
        found_scl = False
        found_sda = False
        aborted = False

        for row in trace[i:]:
            inputs = row.get('inputs', {})
            if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
                aborted = True
                break
            outputs = row.get('outputs', {})
            if outputs.get('cscl') == expected[0]:
                found_scl = True
            if outputs.get('csda') == expected[1]:
                found_sda = True
            if found_scl and found_sda:
                break

        if aborted or not (found_scl and found_sda):
            if aborted:
                continue
            missing = []
            if not found_scl:
                missing.append('cscl')
            if not found_sda:
                missing.append('csda')
            return (None, trace[i]['edge'],
                    f"post-reset raw scl_i/sda_i value {expected!r} was not yet reflected in "
                    f"capture probe(s) before the trace ended: {', '.join(missing)}")

    return (True, None,
            'each non-reset raw scl_i/sda_i presentation was eventually reflected by cscl/csda')

