def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    active = [r for r in trace if out(r, 'filter_cnt') == 1]
    if not active:
        return (None, None, 'filter_cnt never reached the named situation')

    expected = max(1, int(active[0].get('inputs', {}).get('clk_cnt', 0)) >> 2)
    expiries = []
    previous = 0
    for i, row in enumerate(trace):
        current = 1 if out(row, 'filter_cnt_expired') == 1 else 0
        if current and not previous:
            expiries.append(i)
        previous = current

    if len(expiries) < 2:
        return (None, active[0].get('edge'),
                'filter_cnt was reached, but fewer than two filter-counter expiry events were observed')

    for first, second in zip(expiries, expiries[1:]):
        enabled_edges = 0
        for row in trace[first:second]:
            if out(row, 'clk_en') == 1:
                enabled_edges += row.get('held', 1)
        if enabled_edges != expected:
            return (False, trace[second].get('edge'),
                    f'filter sampling interval was {enabled_edges} enabled edges, expected clk_cnt >> 2 = {expected}')

