def decide(trace):
    samples = []
    failures = []

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if inputs.get('ena') != 1 or outputs.get('filter_cnt_expired') != 1:
            continue

        fscl = outputs.get('fscl')
        fsda = outputs.get('fsda')
        if fscl not in (0, 1) or fsda not in (0, 1):
            continue

        samples.append((fscl, fsda, row))
        if len(samples) < 3:
            continue

        scl_history = [x[0] for x in samples[-3:]]
        sda_history = [x[1] for x in samples[-3:]]
        scl_majority = 1 if sum(scl_history) >= 2 else 0
        sda_majority = 1 if sum(sda_history) >= 2 else 0

        bad = []
        if outputs.get('sscl') != scl_majority:
            bad.append(f"sscl={outputs.get('sscl')}, expected majority {scl_majority} of {scl_history}")
        if outputs.get('ssda') != sda_majority:
            bad.append(f"ssda={outputs.get('ssda')}, expected majority {sda_majority} of {sda_history}")
        if bad:
            failures.append((row['edge'], '; '.join(bad)))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not samples or len(samples) < 3:
        return (None, None, 'fewer than three enabled filter-counter expirations were observed; the three-sample majority relation is undecidable')
    return (True, None, 'sSCL and sSDA matched the majority of the three most recent fSCL and fSDA samples at every checked filter-counter expiration')

def decide(trace):
    def value(row, name):
        return row['outputs'].get(name, row['inputs'].get(name))

    hist_scl = [1, 1, 1]
    hist_sda = [1, 1, 1]
    previous_expired = False
    saw_activation = False
    last_edge = None

    for row in trace:
        active = (value(row, 'ena') == 1 and
                  value(row, 'filter_cnt_expired') == 1)
        rising = active and not previous_expired
        previous_expired = active

        if not rising:
            continue

        saw_activation = True
        last_edge = row['edge']
        hist_scl = hist_scl[1:] + [value(row, 'fscl')]
        hist_sda = hist_sda[1:] + [value(row, 'fsda')]

        majority_scl = 1 if sum(hist_scl) >= 2 else 0
        majority_sda = 1 if sum(hist_sda) >= 2 else 0

        actual_scl = value(row, 'sscl')
        actual_sda = value(row, 'ssda')
        if actual_scl != majority_scl or actual_sda != majority_sda:
            return (
                False,
                row['edge'],
                f"at filter expiration, sscl/ssda were "
                f"{actual_scl}/{actual_sda}, expected majority values "
                f"{majority_scl}/{majority_sda} from the three-sample histories"
            )

    if not saw_activation:
        return (None, None, 'filter counter expiration never occurred while ena was high')

    return (True, last_edge, 'sscl and ssda matched the majority of their respective three-sample histories at every filter expiration')

def decide(trace):
    def value(row, name):
        return row.get('outputs', {}).get(name)

    def majority(values):
        return 1 if sum(values) >= 2 else 0

    expirations = []
    samples_scl = []
    samples_sda = []
    previous_expired = 0

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        expired = value(row, 'filter_cnt_expired') == 1
        reset_active = inputs.get('nReset') == 0 or inputs.get('rst') == 1

        if reset_active:
            previous_expired = 0
            samples_scl = []
            samples_sda = []
            continue

        rising_expiration = expired and not previous_expired
        previous_expired = 1 if expired else 0
        if not rising_expiration or inputs.get('ena') != 1:
            continue

        fscl = value(row, 'fscl')
        fsda = value(row, 'fsda')
        if fscl not in (0, 1) or fsda not in (0, 1):
            continue

        samples_scl.append(fscl)
        samples_sda.append(fsda)
        expirations.append((i, row.get('edge'), list(samples_scl[-3:]), list(samples_sda[-3:])))

    if len(expirations) < 3:
        return (None, None, 'fewer than three enabled filter-counter expirations with valid history samples were observed')

    for n in range(2, len(expirations)):
        start, edge, scl_history, sda_history = expirations[n]
        expected_scl = majority(scl_history)
        expected_sda = majority(sda_history)
        end = expirations[n + 1][0] if n + 1 < len(expirations) else None

        scl_seen = False
        sda_seen = False
        last = len(trace) if end is None else end
        for j in range(start, last):
            row = trace[j]
            if value(row, 'sscl') == expected_scl:
                scl_seen = True
            if value(row, 'ssda') == expected_sda:
                sda_seen = True
            if scl_seen and sda_seen:
                break

        if end is not None and (not scl_seen or not sda_seen):
            missing = []
            if not scl_seen:
                missing.append(f"sscl did not reach majority {expected_scl} of {scl_history}")
            if not sda_seen:
                missing.append(f"ssda did not reach majority {expected_sda} of {sda_history}")
            return (False, expirations[n + 1][1], '; '.join(missing))

    return (True, None, 'sSCL and sSDA reached the majority values of their respective three-sample histories after each checked filter-counter expiration')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def majority(history):
        return 1 if sum(history) >= 2 else 0

    # The specification initializes the filter histories high.  A new
    # synchronized sample is represented by the declared fscl/fsda probes
    # when the declared expiration probe is active.
    history_scl = [1, 1, 1]
    history_sda = [1, 1, 1]
    previous_expired = False
    checks = []

    for row in trace:
        inputs = row.get('inputs', {})
        expired = out(row, 'filter_cnt_expired') == 1
        new_sample = (expired and not previous_expired and
                      inputs.get('ena') == 1)
        if new_sample:
            fscl = out(row, 'fscl')
            fsda = out(row, 'fsda')
            if fscl in (0, 1) and fsda in (0, 1):
                history_scl = (history_scl + [fscl])[-3:]
                history_sda = (history_sda + [fsda])[-3:]
                checks.append((row, majority(history_scl), majority(history_sda),
                               list(history_scl), list(history_sda)))
        previous_expired = expired

    if not checks:
        return (None, None, 'the enabled filter-counter expiration situation never occurred')

    unresolved = []
    for row, expected_scl, expected_sda, hscl, hsda in checks:
        start = trace.index(row)
        found = False
        for later in trace[start:]:
            if (out(later, 'sscl') == expected_scl and
                    out(later, 'ssda') == expected_sda):
                found = True
                break
        if not found:
            unresolved.append((row, expected_scl, expected_sda, hscl, hsda))

    if unresolved:
        row, escl, esda, hscl, hsda = unresolved[0]
        return (None, None,
                f'sSCL/sSDA did not yet show majority values {escl}/{esda} '
                f'for histories {hscl}/{hsda} before the trace ended')

    return (True, None,
            'sSCL and sSDA each reached the majority values of their '
            'respective three-sample histories; no unstated latency bound was imposed')

