def decide(trace):
    if not trace:
        return (None, None, 'no trace states were provided')

    pending_scl = 0
    pending_sda = 0
    changes = 0

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        pi = prev.get('inputs', {})
        ri = row.get('inputs', {})
        po = prev.get('outputs', {})
        ro = row.get('outputs', {})

        if pi.get('scl_i') != ri.get('scl_i'):
            pending_scl += 1
        if pi.get('sda_i') != ri.get('sda_i'):
            pending_sda += 1

        if po.get('sscl') != ro.get('sscl'):
            changes += 1
            if pending_scl == 0:
                return (False, row.get('edge'),
                        'sSCL changed without a preceding change on scl_i; the filtered SCL is not a stable internal version')
            pending_scl -= 1

        if po.get('ssda') != ro.get('ssda'):
            changes += 1
            if pending_sda == 0:
                return (False, row.get('edge'),
                        'sSDA changed without a preceding change on sda_i; the filtered SDA is not a stable internal version')
            pending_sda -= 1

    if changes == 0:
        return (True, None, 'sSCL and sSDA remained stable throughout the observed trace')
    return (True, None, 'every observed sSCL or sSDA transition followed a corresponding external line transition')

