def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def operating(row):
        return (row.get('inputs', {}).get('nReset') == 1
                and row.get('inputs', {}).get('rst') == 0)

    active = [operating(row) for row in trace]
    failures = []
    transitions = []

    # A delayed signal must not change while its filtered source is stable.
    # Rows are distinct states, so this compares state order rather than clock
    # counts or a fixed latency.
    for i in range(1, len(trace)):
        if not (active[i] and active[i - 1]):
            continue
        row = trace[i]
        prev = trace[i - 1]

        sscl_changed = out(row, 'sscl') != out(prev, 'sscl')
        ssda_changed = out(row, 'ssda') != out(prev, 'ssda')

        if not sscl_changed and out(row, 'dscl') != out(prev, 'dscl'):
            failures.append((row['edge'], 'dSCL changed while filtered SCL remained stable'))
        if not ssda_changed and out(row, 'dsda') != out(prev, 'dsda'):
            failures.append((row['edge'], 'dSDA changed while filtered SDA remained stable'))

        if sscl_changed:
            transitions.append(('sscl', 'dscl', i, out(row, 'sscl')))
        if ssda_changed:
            transitions.append(('ssda', 'dsda', i, out(row, 'ssda')))

    # Each filtered transition must be followed by the corresponding delayed
    # value.  The delayed value must not already anticipate the transition.
    for source, delayed, i, new_value in transitions:
        trigger = trace[i]
        if out(trigger, delayed) == new_value:
            failures.append((trigger['edge'],
                             f'{delayed} anticipated the {source} transition'))
            continue

        found = False
        for j in range(i + 1, len(trace)):
            if active[j] and out(trace[j], delayed) == new_value:
                found = True
                break
        if not found:
            failures.append((trigger['edge'],
                             f'{delayed} never reflected the new {source} value'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not transitions:
        return (None, None, 'no filtered SCL or SDA transition occurred while operating')
    return (True, None, 'dSCL and dSDA lagged and followed their filtered bus signals')

def decide(trace):
    checked = 0
    previous = None

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        operating = inputs.get('nReset') == 1 and inputs.get('rst') == 0

        if not operating:
            previous = None
            continue

        if previous is None:
            previous = row
            continue

        expected_dscl = previous['outputs'].get('sscl')
        expected_dsda = previous['outputs'].get('ssda')
        actual_dscl = outputs.get('dscl')
        actual_dsda = outputs.get('dsda')
        checked += 1

        if actual_dscl != expected_dscl:
            return (False, row.get('edge'),
                    f"dSCL was {actual_dscl}, expected the preceding filtered SCL value {expected_dscl}")
        if actual_dsda != expected_dsda:
            return (False, row.get('edge'),
                    f"dSDA was {actual_dsda}, expected the preceding filtered SDA value {expected_dsda}")

        previous = row

    if checked == 0:
        return (None, None, 'no consecutive operating states were available to observe delayed dSCL/dSDA values')
    return (True, None, 'dSCL and dSDA matched the preceding operating sscl and ssda values')

def decide(trace):
    def operating(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 1 and inputs.get('rst') == 0

    def value(row, name):
        return row.get('outputs', {}).get(name)

    active = [i for i, row in enumerate(trace) if operating(row)]
    if len(active) < 2:
        return (None, None, 'fewer than two operating states; delayed-version behaviour is not observable')

    failures = []
    checked = False

    for delayed, source in (('dscl', 'sscl'), ('dsda', 'ssda')):
        for pos, i in enumerate(active):
            if pos == 0:
                continue
            checked = True
            prior_source_values = {value(trace[j], source) for j in active[:pos]}
            delayed_value = value(trace[i], delayed)
            if delayed_value not in prior_source_values:
                failures.append(
                    (trace[i].get('edge'),
                     f'{delayed}={delayed_value!r} was not previously present on filtered {source}'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not checked:
        return (None, None, 'no operating state pair was available to observe delayed versions')
    return (True, None, 'dSCL and dSDA contain only values previously observed on filtered SCL and SDA')

