        ssda = value(row, 'ssda')
        dsda = value(row, 'dsda')
        sta = value(row, 'sta_condition')
        sto = value(row, 'sto_condition')

        start_comparison = sscl == 1 and ssda == 0 and dsda == 1
        stop_comparison = sscl == 1 and ssda == 1 and dsda == 0

        if start_comparison or stop_comparison:
            saw_relevant_comparison = True

        if start_comparison and sta != 1:
            return (False, row['edge'],
                    'filtered SDA fell while filtered SCL was high, but sta_condition was not detected')

        if stop_comparison and sto != 1:
            return (False, row['edge'],
                    'filtered SDA rose while filtered SCL was high, but sto_condition was not detected')

        if sta == 1 and not start_comparison:
            return (False, row['edge'],
                    'sta_condition asserted without the corresponding filtered-value comparison')

        if sto == 1 and not stop_comparison:
            return (False, row['edge'],
                    'sto_condition asserted without the corresponding filtered-value comparison')

    if not saw_relevant_comparison:
        return (None, None, 'no relevant filtered SDA transition while filtered SCL was high')

    return (True, None, 'filtered START and/or STOP comparison was detected correctly')

