def decide(trace):
    def special(row):
        outputs = row.get('outputs', {})
        return (outputs.get('active_command') == 1
                and outputs.get('scl_oen') == 1
                and (outputs.get('slave_wait') == 1
                     or outputs.get('scl_sync') == 1))

    occurrences = []
    in_special = False
    start = None

    for i, row in enumerate(trace):
        now = special(row)
        if now and not in_special:
            start = i
            in_special = True
        elif not now and in_special:
            occurrences.append((start, i))
            in_special = False

    if in_special:
        occurrences.append((start, len(trace)))

    if not occurrences:
        return (None, None,
                'no active released-SCL clock-stretching or synchronization interval occurred')

    for start, end in occurrences:
        for row in trace[start:end]:
            if row.get('outputs', {}).get('cmd_ack') == 1:
                return (False, row['edge'],
                        'cmd_ack completed during a released-SCL interval affected by clock stretching or multi-master synchronization')

    for start, end in occurrences:
        for row in trace[end:]:
            if row.get('outputs', {}).get('cmd_ack') == 1:
                return (True, row['edge'],
                        'cmd_ack completed only after the clock-stretching or synchronization interval ended')

    return (None, None,
            'the special interval occurred, but no later cmd_ack was observed before the trace ended')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def aborted(row):
        return (row.get('inputs', {}).get('rst') == 1 or
                row.get('inputs', {}).get('nReset') == 0 or
                out(row, 'al') == 1)

    def affected(row):
        return (out(row, 'active_command') == 1 and
                out(row, 'al') != 1 and
                (out(row, 'slave_wait') == 1 or
                 out(row, 'scl_sync') == 1))

    starts = []
    for i, row in enumerate(trace):
        if affected(row) and (i == 0 or not affected(trace[i - 1])):
            starts.append(i)

    if not starts:
        return (None, None,
                'no active released-SCL stretching or multi-master synchronization interval occurred')

    for start in starts:
        end = start
        while end < len(trace) and affected(trace[end]):
            if aborted(trace[end]):
                break
            if out(trace[end], 'cmd_ack') == 1:
                return (False, trace[end]['edge'],
                        'cmd_ack asserted before the stretching or synchronization condition cleared')
            end += 1

        if any(aborted(trace[k]) for k in range(start, min(end, len(trace)))):
            continue

        if end >= len(trace):
            return (None, None,
                    'the affected interval remained open until the trace ended')

        if aborted(trace[end]):
            continue

        for k in range(end, len(trace)):
            if aborted(trace[k]):
                break
            if out(trace[k], 'cmd_ack') == 1:
                return (True, trace[k]['edge'],
                        'cmd_ack occurred after the stretched or synchronized interval completed')

        return (None, None,
                'the interval completed, but the trace ended before a subsequent cmd_ack was observed')

    return (None, None,
            'all affected intervals were aborted by reset or arbitration loss')

