def decide(trace):
    from specflow.refmodel.temporal import after, edges, throughout, worst

    def out(row, name):
        return row['outputs'].get(name)

    # Use the declared probe signature of slave clock stretching.  This avoids
    # assuming an encoding for cmd, which is not provided by an encoding table.
    def waiting(row):
        return (
            out(row, 'active_command') == 1 and
            row['inputs'].get('ena') == 1 and
            out(row, 'slave_wait') == 1 and
            out(row, 'scl_oen') == 1 and
            out(row, 'sscl') == 0
        )

    windows = after(
        trace,
        waiting,
        until=lambda row: out(row, 'slave_wait') == 0
    )

    verdicts = [
        throughout(
            window,
            lambda row: out(row, 'scl_oen') == 1,
            after_activation=True
        )
        for window in windows
    ]
    wait_result = worst(verdicts)
    if wait_result[0] is False:
        return wait_result
    if not windows:
        return wait_result

    # Confirm the route's contrasting case: ordinary command progress must be
    # observable as a transition away from released SCL when waiting is absent.
    falling_edges = edges(trace, 'scl_oen', 'fall')
    ordinary_advance = False
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        if current['edge'] not in falling_edges:
            continue
        if (
            out(previous, 'active_command') == 1 and
            previous['inputs'].get('ena') == 1 and
            out(previous, 'slave_wait') == 0 and
            out(previous, 'sscl') == 1 and
            out(previous, 'scl_oen') == 1 and
            out(current, 'scl_oen') == 0
        ):
            ordinary_advance = True
            break

    if not ordinary_advance:
        return (None, None, 'slave_wait behavior was observed, but the contrasting non-wait scl_oen advance was not exercised')
    return wait_result

