        inputs = row.get('inputs', {})
        return (outputs.get('slave_wait') == 1 and
                outputs.get('active_command') == 1 and
                inputs.get('ena') == 1)

    windows = after(
        trace,
        active,
        until=lambda r: r.get('outputs', {}).get('slave_wait') == 0
    )

    if not windows:
        return (None, None, 'slave_wait was never active during an enabled active command')

    results = []
    evidence_missing = False

    for w in windows:
        verdict = throughout(
            w,
            lambda r: r.get('outputs', {}).get('scl_oen') == 1,
            after_activation=True
