                if wait_ended:
                    current = outputs.get('scl_oen')
                    if current != prior:
                        advanced = True
                        break
                    prior = current
        if not advanced:
            evidence_missing = True

    if evidence_missing:
        return (None, None,
                'slave_wait was observed, but no post-wait scl_oen advance showed the routed contrast')

    return (True, None,
            'scl_oen remained released throughout each slave_wait window and advanced after the wait ended')

