        if value(row, 'slave_wait') != 1:
            return False
        if value(row, 'scl_oen') != 1:
            return False
        # The wait must belong to a command-time SCL release, not the
        # initially released idle/reset output.
        return any(i <= row['index'] for i in release_indices)

