def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def out(row, name):
        return row['outputs'].get(name)

    # `scl_oen == 1` is also the reset/idle level.  Anchor the situation
    # after the command-time transition into release, rather than opening on
    # that level merely because it was already present at reset.
    release_rows = set(edges(trace, 'scl_oen', 'rise'))
    command_release_rows = set()
    command_seen = False
    for row in trace:
        if out(row, 'active_command') == 1 and row['inputs'].get('ena') == 1:
            command_seen = True
        if command_seen and row['index'] in release_rows:
            command_release_rows.add(row['index'])

    def applies(row):
        return (
            row['index'] in command_release_rows and
            out(row, 'active_command') == 1 and
            row['inputs'].get('ena') == 1 and
            out(row, 'slave_wait') == 1
        )

    windows = after(
        trace,
        applies,
        until=lambda row: out(row, 'slave_wait') == 0
    )

    wait_results = [
        throughout(
            window,
            lambda row: out(row, 'scl_oen') == 1,
            after_activation=True
        )
        for window in windows
    ]
    wait_result = worst(wait_results)
    if wait_result[0] is False:
        return wait_result
    if not windows:
        return wait_result

    # The routed `shows` field supplies the necessary contrasting case:
    # after waiting ends, a command with filtered SCL high can leave the
    # released phase and advance its SCL timing output.  Do not convict when
    # this trace supplies only the wait-side evidence.
    first_wait_edge = min(window.edge for window in windows)
    contrast_edge = None
    for previous, current in zip(trace, trace[1:]):
        if current['edge'] <= first_wait_edge:
            continue
        if (
            out(previous, 'active_command') == 1 and
            out(current, 'active_command') == 1 and
