from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

def decide(trace):
    def holds(row, cond):
        return all(row["outputs"].get(port) == value
                   for port, value in cond.items())

    phase_changes = edges(trace, "scl_oen", "change")

    def active_enabled(row):
        return (holds(row, {"active_command": 1})
                and row["inputs"].get("ena") == 1
                and row["inputs"].get("nReset") == 1
                and row["inputs"].get("rst") == 0)

    def closes(row):
        return (holds(row, {"idle": 1})
                or holds(row, {"al": 1}))

    def aborts(row):
        return (row["inputs"].get("nReset") == 0
                or row["inputs"].get("rst") == 1
                or holds(row, {"al": 1}))

    windows = after(trace, active_enabled, until=closes, aborts=aborts)
    return worst([
        eventually(
            window,
            lambda row: row["edge"] in phase_changes,
            strong=True,
            after_activation=True
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    changes = edges(trace, "scl_oen", "change")
    sequence_probes = (
        "start_sequence",
        "stop_sequence",
        "read_sequence",
        "write_sequence",
    )
    verdicts = []

    for probe in sequence_probes:
        def active(row, probe=probe):
            return (
                row["inputs"].get("ena") == 1
                and row["outputs"].get(probe) == 1
            )

        def closes(row, probe=probe):
            return row["outputs"].get(probe) != 1

        windows = after(trace, active, until=closes)
        verdicts.extend(
            eventually(
                window,
                lambda row: row["edge"] in changes,
                after_activation=False,
                strong=False,
            )
            for window in windows
        )

    return worst(verdicts)

def decide(trace):
    segments = []
    current = []
    saw_aborted = False

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        active = outputs.get('active_command') == 1
        enabled = inputs.get('ena') == 1
        reset = inputs.get('nReset') == 0 or inputs.get('rst') == 1

        if active and enabled and not reset:
            current.append(row)
        else:
            if current:
                segments.append(current)
                current = []
            if reset and active:
                saw_aborted = True

    if current:
        segments.append(current)

    if not segments:
        return (None, None, 'no enabled active command sequence occurred')

    for segment in segments:
        changes = []
        for prev, row in zip(segment, segment[1:]):
            if prev.get('outputs', {}).get('scl_oen') != row.get('outputs', {}).get('scl_oen'):
                changes.append(row)
        if not changes:
            edge = segment[-1].get('edge')
            return (False, edge, 'scl_oen did not change phase during the enabled active command sequence')

    edge = segments[0][0].get('edge')
    return (True, edge, 'scl_oen exhibited timing-phase changes during every enabled active command sequence')

