def decide(trace):
    seqs = ("start_sequence", "stop_sequence", "read_sequence", "write_sequence")

    def out(row, name):
        return row.get("outputs", {}).get(name)

    def eligible(row):
        return (
            row.get("inputs", {}).get("ena") == 1
            and row.get("inputs", {}).get("nReset") == 1
            and row.get("inputs", {}).get("rst") == 0
            and out(row, "al") == 0
            and out(row, "slave_wait") != 1
        )

    observations = []
    for i, row in enumerate(trace):
        if not eligible(row):
            continue

        kind = None
        for name in seqs:
            if out(row, name) == 1 and (
                i == 0 or out(trace[i - 1], name) != 1
            ):
                kind = name
                break
        if kind is None:
            continue

        clk_cnt = row.get("inputs", {}).get("clk_cnt")
        din = row.get("inputs", {}).get("din")
        bus_scl = row.get("inputs", {}).get("scl_i")
        bus_sda = row.get("inputs", {}).get("sda_i")
        ack = None
        stable = True

        for j in range(i + 1, len(trace)):
            current = trace[j]
            if (
                current.get("inputs", {}).get("scl_i") != bus_scl
                or current.get("inputs", {}).get("sda_i") != bus_sda
                or current.get("inputs", {}).get("clk_cnt") != clk_cnt
            ):
                stable = False
                break
            if not eligible(current):
                stable = False
                break
            if out(current, "cmd_ack") == 1:
                ack = j
                break

        if stable and ack is not None:
            latency = sum(r.get("held", 1) for r in trace[i:ack])
            observations.append((kind, din, clk_cnt, latency, row.get("edge")))

    comparisons = []
    for a in range(len(observations)):
        for b in range(a + 1, len(observations)):
            ka, da, ca, la, ea = observations[a]
            kb, db, cb, lb, eb = observations[b]
            if ka != kb or da != db or ca == cb:
                continue
            if ca < cb:
                comparisons.append((ca, cb, la, lb, ea, eb))
            else:
                comparisons.append((cb, ca, lb, la, eb, ea))

    if not comparisons:
        return (None, None, "no pair of comparable completed command sequences used different clk_cnt values")

    for low, high, low_latency, high_latency, low_edge, high_edge in comparisons:
        if high_latency <= low_latency:
            return (
                False,
                high_edge,
                f"cmd_ack latency was {high_latency} edges for clk_cnt={high}, not greater than {low_latency} edges for clk_cnt={low}; the programmed counter delay did not increase"
            )

    return (
        True,
        None,
        f"all {len(comparisons)} comparable command pairs showed greater cmd_ack latency for the larger clk_cnt"
    )

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def active_start(i):
        if i == 0:
            previous = 0
        else:
            previous = out(trace[i - 1], 'active_command')
        row = trace[i]
        return (previous == 0 and out(row, 'active_command') == 1
                and inp(row, 'ena') == 1
                and inp(row, 'nReset') == 1
                and inp(row, 'rst') == 0
                and out(row, 'al') == 0
                and out(row, 'slave_wait') == 0)

    transactions = []
    for start in [i for i in range(len(trace)) if active_start(i)]:
        first = trace[start]
        end = None
        invalid = False
        for j in range(start, len(trace)):
            row = trace[j]
            if (inp(row, 'ena') != 1 or inp(row, 'nReset') != 1
                    or inp(row, 'rst') != 0 or out(row, 'al') != 0
                    or out(row, 'slave_wait') != 0):
                invalid = True
                break
            if (inp(row, 'scl_i') != inp(first, 'scl_i')
                    or inp(row, 'sda_i') != inp(first, 'sda_i')):
                invalid = True
                break
            if j > start and out(row, 'cmd_ack') == 1 \
                    and out(trace[j - 1], 'cmd_ack') != 1:
                end = j
                break
        if invalid or end is None:
            continue
        latency = sum(int(trace[k].get('held', 1)) for k in range(start, end + 1))
        transactions.append({
            'start': start,
            'end': end,
            'clk_cnt': inp(first, 'clk_cnt'),
            'cmd': inp(first, 'cmd'),
            'din': inp(first, 'din'),
            'latency': latency
        })

    comparisons = []
    for i, left in enumerate(transactions):
        for right in transactions[i + 1:]:
            if (left['cmd'] == right['cmd'] and left['din'] == right['din']
                    and left['clk_cnt'] != right['clk_cnt']):
                comparisons.append((left, right))

    if not comparisons:
        return (None, None,
                'no pair of otherwise equivalent completed transactions with different clk_cnt values')

    for left, right in comparisons:
        if left['latency'] == right['latency']:
            return (False, trace[right['end']]['edge'],
                    'changing clk_cnt did not change completion latency; the counter was not visibly loaded and decremented from the prescale input')

    return (True, trace[comparisons[-1][1]['end']]['edge'],
            'completed equivalent transactions with different clk_cnt values had different counter-driven latencies')

def decide(trace):
    sequence_names = ("start_sequence", "stop_sequence", "read_sequence", "write_sequence")

    def value(row, name):
        return row.get("outputs", {}).get(name)

    def inputs(row):
        return row.get("inputs", {})

    def applicable(row):
        inp = inputs(row)
        return (
            inp.get("ena") == 1
            and inp.get("nReset") == 1
            and inp.get("rst") == 0
            and value(row, "al") == 0
            and value(row, "slave_wait") != 1
        )

    attempts = []
    for i, row in enumerate(trace):
        if not applicable(row):
            continue

        sequence = None
        for name in sequence_names:
            if value(row, name) == 1 and (
                i == 0 or value(trace[i - 1], name) != 1
            ):
                sequence = name
                break
        if sequence is None:
            continue

        clk_cnt = inputs(row).get("clk_cnt")
        if not isinstance(clk_cnt, int) or clk_cnt < 0:
            continue

        ack_index = None
        aborted = False
        for j in range(i + 1, len(trace)):
            current = trace[j]
            current_inputs = inputs(current)
            if (
                current_inputs.get("ena") != 1
                or current_inputs.get("nReset") != 1
                or current_inputs.get("rst") != 0
                or value(current, "al") == 1
                or value(current, "slave_wait") == 1
                or current_inputs.get("clk_cnt") != clk_cnt
            ):
                aborted = True
                break
            if value(current, "cmd_ack") == 1:
                ack_index = j
                break

        if aborted:
            continue
        if ack_index is None:
            return (
                False,
                row.get("edge"),
                f"{sequence} started with clk_cnt={clk_cnt}, but no cmd_ack appeared before the trace ended"
            )

        elapsed = sum(
            trace[k].get("held", 1)
            for k in range(i, ack_index)
        )
        attempts.append((sequence, clk_cnt, elapsed, trace[ack_index].get("edge")))

    if not attempts:
        return (None, None, "no supported command timing window occurred")

    for sequence, clk_cnt, elapsed, ack_edge in attempts:
        if elapsed < clk_cnt:
            return (
                False,
                ack_edge,
                f"{sequence} produced cmd_ack after {elapsed} clock edges with clk_cnt={clk_cnt}; the counter-driven delay must include {clk_cnt} decrementing edges"
            )

    return (
        True,
        None,
        f"all {len(attempts)} supported command completions occurred only after their stated clk_cnt decrement intervals"
    )

def decide(trace):
    sequence_names = ("start_sequence", "stop_sequence", "read_sequence", "write_sequence")

    def out(row, name):
        return row.get("outputs", {}).get(name)

    def inp(row, name):
        return row.get("inputs", {}).get(name)

    def active(row):
        return (
            inp(row, "ena") == 1
            and inp(row, "nReset") == 1
            and inp(row, "rst") == 0
            and out(row, "al") != 1
            and out(row, "slave_wait") != 1
        )

    decisions = []
    for i, row in enumerate(trace):
        if not active(row):
            continue

        sequence = None
        for name in sequence_names:
            if out(row, name) == 1 and (
                i == 0 or out(trace[i - 1], name) != 1
            ):
                sequence = name
                break
        if sequence is None:
            continue

        clk_cnt = inp(row, "clk_cnt")
        if not isinstance(clk_cnt, int) or clk_cnt < 0:
            continue

        saw_counter_progress = False
        completed = False
        aborted = False

        for j in range(i + 1, len(trace)):
            current = trace[j]
            if not active(current) or inp(current, "clk_cnt") != clk_cnt:
                aborted = True
                break

            if out(current, "clk_en") == 1 or out(current, "cnt_zero") == 1:
                saw_counter_progress = True

            if out(current, "cmd_ack") == 1:
                completed = True
                if not saw_counter_progress:
                    decisions.append(
                        (
                            False,
                            current.get("edge"),
                            f"{sequence} produced cmd_ack before any observed counter-driven progression; the counter must be loaded from clk_cnt and decremented before completion"
                        )
                    )
                else:
                    decisions.append(
                        (
                            True,
                            current.get("edge"),
                            f"{sequence} completed only after observed counter-driven progression with clk_cnt={clk_cnt}; no exact latency was assumed"
                        )
                    )
                break

        if aborted or not completed:
            continue

    if not decisions:
        return (None, None, "no supported command completed within an uninterrupted counter-operating window")

    for ok, edge, detail in decisions:
        if not ok:
            return (False, edge, detail)
    return (True, None, f"all {len(decisions)} completed command windows showed counter-driven progression before cmd_ack")

