def decide(trace):
    def active(row):
        return (row['inputs'].get('ena') == 1 and
                row['outputs'].get('cnt_zero') == 1)

    occurrences = []
    previous = False
    for row in trace:
        current = active(row)
        if current and not previous:
            occurrences.append(row)
        previous = current

    if not occurrences:
        return (None, None, 'the timing-counter expiration activation never occurred')

    for row in occurrences:
        if row['outputs'].get('clk_en') != 1:
            return (False, row['edge'],
                    'when the counter expires while ena is high, clk_en is not asserted')

