        return (None, None, 'no filtered STOP occurred during an active START, WRITE, or READ command')

    for event in stop_events:
        event_index = event.get('index')
        position = next(
            (i for i, row in enumerate(trace) if row.get('index') == event_index),
            None
        )
        if position is None:
            continue

        for row in trace[position:]:
            if out(row, 'al') == 1:
                break
        else:
            return (
                False,
                event.get('edge'),
                'al did not assert after a filtered STOP during an active non-STOP command'
            )

    return (
        True,
        stop_events[0].get('edge'),
        'al asserted after each filtered STOP during an active non-STOP command'
    )

