def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

    def holds(row, cond):
        for port, value in cond.items():
            values = row.get("outputs", {})
            if port not in values:
                values = row.get("inputs", {})
            if values.get(port) != value:
                return False
        return True

    def any_condition(alternatives):
        return lambda row: any(holds(row, cond) for cond in alternatives)

    # The READ command's numeric encoding is not authoritative here; the
    # declared read_sequence probe identifies the READ sampling phase.
    applies = lambda row: (
        holds(row, {"ena": 1, "read_sequence": 1, "filtered_scl_rise": 1})
    )
    aborts = any_condition([
        {"al": 1},
        {"nReset": 0},
        {"rst": 1},
    ])

    windows = after(trace, applies, until=WHILE_ACTIVE, aborts=aborts)
    return worst([
        throughout(
            window,
            lambda row: (
                row["outputs"].get("dout") == row["outputs"].get("ssda")
            ),
            after_activation=False,
        )
        for window in windows
    ])

def decide(trace):
    def active(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (inputs.get('ena') == 1 and
                outputs.get('read_sequence') == 1 and
                outputs.get('filtered_scl_rise') == 1)

    def aborted(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (outputs.get('al') == 1 or
                inputs.get('nReset') == 0 or
                inputs.get('rst') == 1)

    events = []
    for row in trace:
        if aborted(row):
            continue
        if active(row):
            events.append(row)

    if not events:
        return (None, None,
                'no non-aborted filtered SCL rising edge occurred during the READ data-sampling phase')

    for row in events:
        outputs = row.get('outputs', {})
        actual = outputs.get('dout')
        expected = outputs.get('ssda')
        if actual != expected:
            return (False, row.get('edge'),
                    f'dout was {actual}, expected filtered SDA ssda={expected} '
                    'at the READ data-sampling event')

    return (True, events[-1].get('edge'),
            f'{len(events)} READ data-sampling event(s) captured the filtered SDA value')

