from specflow.refmodel.temporal import TO_END, WHILE_ACTIVE, after, eventually, throughout, worst


def decide(trace):
    def holds(cond):
        def predicate(row):
            for port, value in cond.items():
                values = row.get('outputs', {})
                if port not in values:
                    values = row.get('inputs', {})
                if values.get(port) != value:
                    return False
            return True
        return predicate

    def activation_for(cmd_value):
        return lambda row: (
            row.get('outputs', {}).get('idle') == 1
            and row.get('inputs', {}).get('ena') == 1
            and row.get('outputs', {}).get('clk_en') == 1
            and row.get('inputs', {}).get('cmd') == cmd_value
        )

    supported = []
    for value, name in ((1, 'START'), (2, 'STOP'), (8, 'READ'), (4, 'WRITE')):
        windows = after(
            trace,
            activation_for(value),
            until=holds({'cmd_ack': 1})
        )
        supported.extend(
            eventually(
                window,
                lambda row: row.get('outputs', {}).get('scl_oen') == 0,
                strong=True,
                after_activation=False
            )
            for window in windows
        )

    nop_windows = after(
        trace,
        activation_for(0),
        until=WHILE_ACTIVE
    )
    nop = [
        throughout(
            window,
            lambda row: row.get('outputs', {}).get('scl_oen') == 1,
            after_activation=False
        )
        for window in nop_windows
    ]

    return worst(supported + nop)

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst


def decide(trace):
    def value(row, port):
        outputs = row.get('outputs', {})
        if port in outputs:
            return outputs.get(port)
        return row.get('inputs', {}).get(port)

    def idle_command(row, command):
        return (
            value(row, 'idle') == 1
            and value(row, 'ena') == 1
            and value(row, 'clk_en') == 1
            and value(row, 'cmd') == command
        )

    def still_qualified(command):
        return lambda row: (
            value(row, 'idle') == 1
            and value(row, 'ena') == 1
            and value(row, 'cmd') == command
        )

    verdicts = []

    # No operation must remain in the idle/released output condition.  The
    # window is co-extensive with the idle-qualified no-operation situation;
    # it does not run into a later command in the same trace.
    nop_windows = after(
        trace,
        lambda row: idle_command(row, 0),
        until=WHILE_ACTIVE
    )
    verdicts.extend(
        throughout(
            window,
            lambda row: value(row, 'scl_oen') == 1,
            after_activation=False
        )
        for window in nop_windows
    )

    # START, STOP, READ and WRITE are represented by their normalized command
    # values.  A command-specific low phase on scl_oen is positive observable
    # evidence through REQ-0008.  STOP may legitimately remain released on
    # this single observable, so lack of such evidence is UNKNOWN rather than
    # a failure.
    for command, name in ((1, 'START'), (2, 'STOP'), (8, 'READ'), (4, 'WRITE')):
        windows = after(
            trace,
            lambda row, command=command: idle_command(row, command),
            until=lambda row, command=command: not still_qualified(command)(row)
        )
        for window in windows:
            low_rows = [
                row for row in window.rows
                if value(row, 'scl_oen') == 0
            ]
            if low_rows:
                verdicts.append(
                    (True, low_rows[0].get('edge'),
                     f'{name} decoding produced the command-specific scl_oen activity')
                )
            else:
                verdicts.append(
                    (None, window.edge,
                     f'{name} decoding is not distinguishable from release on scl_oen alone')
                )

    return worst(verdicts)

def decide(trace):
    def val(row, port):
        if port in row.get('outputs', {}):
            return row['outputs'][port]
        if port in row.get('inputs', {}):
            return row['inputs'][port]
        return None

    def qualifies(row, command):
        return (
            val(row, 'idle') == 1
            and val(row, 'ena') == 1
            and val(row, 'clk_en') == 1
            and val(row, 'cmd') == command
        )

    verdicts = []
    commands = ((1, 'START'), (2, 'STOP'), (8, 'READ'), (4, 'WRITE'))

    for command, name in commands:
        for i, row in enumerate(trace):
            if not qualifies(row, command):
                continue

            j = i + 1
            left_idle = False
            found_drive_transition = False
            previous = row

            while j < len(trace):
                current = trace[j]
                if val(current, 'idle') != 1:
                    left_idle = True
                elif left_idle:
                    break

                if (
                    val(previous, 'scl_oen') != 0
                    and val(current, 'scl_oen') == 0
                ):
                    found_drive_transition = True
                    verdicts.append((
                        True,
                        current.get('edge'),
                        f'{name} decoding reached a command-specific scl_oen drive-low state'
                    ))
                    break

                previous = current
                j += 1

            if not found_drive_transition:
                if j >= len(trace) and left_idle:
                    verdicts.append((
                        None,
                        row.get('edge'),
                        f'{name} command sequence remained open before scl_oen activity was observed'
                    ))
                else:
                    verdicts.append((
                        False,
                        row.get('edge'),
                        f'{name} was decoded at the idle clk_en opportunity but no command-specific scl_oen drive-low transition occurred before returning idle'
                    ))

    for i, row in enumerate(trace):
        if not qualifies(row, 0):
            continue

        j = i
        while j < len(trace) and qualifies(trace[j], 0):
            if val(trace[j], 'scl_oen') != 1:
                verdicts.append((
                    False,
                    trace[j].get('edge'),
                    'no-operation decoding must retain the idle/released scl_oen condition'
                ))
                break
            j += 1
        else:
            verdicts.append((
                True,
                row.get('edge'),
                'no-operation decoding retained the idle/released scl_oen condition'
            ))

    if not verdicts:
        return (None, None, 'the idle decoding opportunity never occurred')

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return (True, None, 'all observed idle command-decoding cases matched their scl_oen behavior')

