from specflow.refmodel.temporal import after, edges, eventually, pulse, worst


def decide(trace):
    # The command encoding has no authoritative table.  Qualify the trigger
    # with the declared STOP-sequence probe and its released-line signature.
    sda_release = edges(trace, "sda_oen", "rise")

    def completed_stop(row):
        return (
            row["edge"] in sda_release
            and row["outputs"].get("scl_oen") == 1
            and row["outputs"].get("sda_oen") == 1
            and row["outputs"].get("stop_sequence") == 1
            and row["inputs"].get("ena") == 1
        )

    def acknowledged(row):
        return row["outputs"].get("cmd_ack") == 1

    def reset_active(row):
        return (
            row["inputs"].get("nReset") == 0
            or row["inputs"].get("rst") == 1
        )

    windows = after(
        trace,
        completed_stop,
        until=acknowledged,
        aborts=reset_active,
    )

    follows = True
    verdicts = []
    for window in windows:
        verdicts.append(
            eventually(
                window,
                lambda row: row["outputs"].get("idle") == 1,
                after_activation=follows,
                strong=True,
            )
        )
        verdicts.append(
            pulse(
                window,
                "cmd_ack",
                width=1,
                active=1,
                after_activation=follows,
            )
        )

    return worst(verdicts)

def decide(trace):
    activations = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        po = prev['outputs']
        o = row['outputs']
        if (po.get('stop_sequence') == 1 and
                o.get('stop_sequence') == 1 and
                po.get('sda_oen') == 0 and
                o.get('sda_oen') == 1 and
                o.get('scl_oen') == 1):
            activations.append(i)

    if not activations:
        return (None, None, 'completed STOP-condition phase never occurred')

    for i in activations:
        ack = None
        aborted = False
        for j in range(i + 1, len(trace)):
            row = trace[j]
            if row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1:
                aborted = True
                break
            if row['outputs'].get('cmd_ack') == 1:
                ack = j
                break

        if aborted:
            continue
        if ack is None:
            return (False, trace[i]['edge'],
                    'STOP completion occurred but cmd_ack never pulsed')

        ack_row = trace[ack]
        if ack_row['outputs'].get('idle') != 1:
            return (False, ack_row['edge'],
                    'cmd_ack asserted before the FSM returned to idle')

        total_high_edges = 0
        k = ack
        saw_low_after = False
        while k < len(trace) and trace[k]['outputs'].get('cmd_ack') == 1:
            total_high_edges += trace[k]['held']
            k += 1
        if k < len(trace):
            saw_low_after = True

        if total_high_edges != 1:
            return (False, ack_row['edge'],
                    f'cmd_ack was high for {total_high_edges} edges, expected exactly one clock')
        if not saw_low_after:
            return (None, ack_row['edge'],
                    'cmd_ack became high for one observed edge but its pulse end was not observed')

    return (True, None, 'FSM returned to idle and cmd_ack pulsed high for exactly one clock')

