    from specflow.refmodel.temporal import edges

    rises = edges(trace, "filtered_scl_rise", "rise")
    activations = [
        row for row in trace
        if row["edge"] in rises
        and row["inputs"].get("ena") == 1
        and row["inputs"].get("scl_i") == 1
    ]

    if not activations:
        return (None, None, "no qualifying filtered SCL rising edge occurred")

