def decide(trace):
    outputs = lambda row: row.get('outputs', {})

    # The command encoding is not supplied by an encoding table.  Recognize
    # the READ transaction from its declared state/edge signature instead.
    activations = []
    for i, row in enumerate(trace):
        out = outputs(row)
        if out.get('read_sequence') == 1 and out.get('filtered_scl_rise') == 1:
            activations.append(i)

    if not activations:
        return (None, None,
                'no filtered SCL rising-edge completion was observed while the declared READ sequence was active')

    for i in activations:
        for later in trace[i + 1:]:
            out = outputs(later)
            if out.get('idle') == 1 and out.get('cmd_ack') == 1:
                break
        else:
            return (False, trace[i].get('edge'),
                    'after the READ bit completion, the FSM never reached idle with cmd_ack asserted')

    return (True, None,
            'each observed READ bit completion was followed by idle with cmd_ack asserted')

