def decide(trace):
    # The physical line level is an external input and is not a DUT output.
    # The routed observation therefore requires both sides of each output-enable
    # signature rather than checking only REQ-0005's high-level case.
    result = []
    for port, line in (("scl_oen", "SCL"), ("sda_oen", "SDA")):
        rows = [r for r in trace if port in r.get("outputs", {})]
        high = [r for r in rows if r["outputs"][port] == 1]
        low = [r for r in rows if r["outputs"][port] == 0]
        if not high:
            result.append((None, None, f"{port} never showed high; the released-line case was not exercised"))
        elif not low:
            result.append((None, None, f"{port} never showed low; the routed two-case signature for {line} was not exercised"))
        else:
            result.append((True, high[0]["edge"], f"{port}=1 shows {line} released and {port}=0 shows {line} actively driven low"))

    failures = [v for v in result if v[0] is False]
    if failures:
        return failures[0]
    unknowns = [v for v in result if v[0] is None]
    if unknowns:
        return unknowns[0]
    return (True, None, "Both output-enable controls showed their released-high and driven-low cases")

