def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def active(row):
        outputs = row.get('outputs', {})
        return any(outputs.get(p, 0) == 1 for p in sequence_ports)

    def aborted(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (inputs.get('nReset') == 0 or
                inputs.get('rst') == 1 or
                outputs.get('al') == 1)

    terminal_indices = []
    for i in range(1, len(trace)):
        row = trace[i]
        if (active(trace[i - 1]) and not active(row) and
                row.get('inputs', {}).get('ena') == 1 and
                not aborted(row)):
            terminal_indices.append(i)

    if not terminal_indices:
        return (None, None,
                'no START, STOP, READ, or WRITE sequence reached its terminal phase')

    unknown = False
    for terminal_i in terminal_indices:
        ack_i = None
        aborted_before_ack = False

        for j in range(terminal_i + 1, len(trace)):
            row = trace[j]
            if aborted(row):
                aborted_before_ack = True
                break
            if row.get('outputs', {}).get('cmd_ack') == 1:
                ack_i = j
                break

        if aborted_before_ack:
            unknown = True
            continue

        if ack_i is None:
            return (False, trace[terminal_i].get('edge'),
                    'sequence completed but cmd_ack was not asserted; expected exactly one clk cycle')

        # The acknowledgement must begin after the terminal transition.
        if trace[ack_i - 1].get('outputs', {}).get('cmd_ack') == 1:
            return (False, trace[ack_i].get('edge'),
                    'cmd_ack was already asserted before sequence completion')

        # Sum held edges across all consecutive distinct rows in the high run.
        width = 0
        j = ack_i
        while j < len(trace) and trace[j].get('outputs', {}).get('cmd_ack') == 1:
            width += trace[j].get('held', 1)
            j += 1

        if width != 1:
            return (False, trace[ack_i].get('edge'),
                    f'cmd_ack was high for {width} clk edges; expected exactly one clk cycle')

        # A trace ending while the pulse is high does not show that it ended.
        if j == len(trace):
            unknown = True
            continue

    if unknown:
        return (None, None,
                'the sequence was aborted or the one-cycle cmd_ack pulse was not fully observed')

    return (True, None,
            'each observed completed START, STOP, READ, or WRITE sequence had a one-clk cmd_ack pulse')

def decide(trace):
    supported = {1, 2, 4, 8}
    activations = []

    def qualified(row):
        return (
            row['inputs'].get('ena') == 1
            and row['inputs'].get('cmd') in supported
            and row['inputs'].get('nReset') != 0
            and row['inputs'].get('rst') != 1
            and row['outputs'].get('al', 0) != 1
        )

    for i, row in enumerate(trace):
        if not qualified(row):
            continue
        previous = trace[i - 1] if i else None
        if previous is None or not qualified(previous):
            activations.append(i)

    if not activations:
        return (None, None, 'no supported START, STOP, READ, or WRITE command sequence was activated')

    for start in activations:
        ack = None
        aborted = False
        for j in range(start + 1, len(trace)):
            row = trace[j]
            if row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1:
                aborted = True
                break
            if row['outputs'].get('al', 0) == 1:
                aborted = True
                break
            if row['outputs'].get('cmd_ack') == 1:
                ack = j
                break

        if aborted:
            continue
        if ack is None:
            return (False, trace[start]['edge'], 'supported command sequence completed in the observed transaction without cmd_ack')

        end = ack
        held_high = 0
        while end < len(trace) and trace[end]['outputs'].get('cmd_ack') == 1:
            held_high += trace[end]['held']
            end += 1

        if held_high != 1:
            return (False, trace[ack]['edge'], f'cmd_ack was asserted for {held_high} clock edges; expected exactly one')
        if end == len(trace):
            return (None, trace[ack]['edge'], 'cmd_ack was high for one observed clock but its deassertion was not observed')

    if all(
        any(
            trace[j]['outputs'].get('cmd_ack') == 1
            for j in range(i + 1, len(trace))
        )
        for i in activations
    ):
        return (True, None, 'each activated, non-aborted command sequence produced a one-clock cmd_ack pulse')
    return (None, None, 'all activated command sequences were aborted before completion')

def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def outputs(row):
        return row.get('outputs', {})

    def active(row):
        out = outputs(row)
        return any(out.get(port, 0) == 1 for port in sequence_ports)

    def aborted(row):
        inp = row.get('inputs', {})
        out = outputs(row)
        return (inp.get('nReset') == 0 or
                inp.get('rst') == 1 or
                out.get('al', 0) == 1)

    terminals = []
    active_start = None

    for i, row in enumerate(trace):
        if active(row):
            if active_start is None:
                active_start = i
        elif active_start is not None:
            terminals.append((active_start, i))
            active_start = None

    if not terminals:
        return (None, None,
                'no START, STOP, READ, or WRITE sequence reached its terminal state')

    unknown = False

    for start_i, terminal_i in terminals:
        # A reset or arbitration loss means this was an aborted command, not
        # a completed sequence that owed an acknowledgement.
        if any(aborted(trace[j]) for j in range(start_i, terminal_i + 1)):
            unknown = True
            continue

        # An acknowledgement before the sequence ended is not an end-of-
        # sequence acknowledgement.
        early = [j for j in range(start_i, terminal_i)
                 if outputs(trace[j]).get('cmd_ack', 0) == 1]
        if early:
            return (False, trace[early[0]].get('edge'),
                    'cmd_ack was asserted before the sequence ended')

        ack_i = None
        for j in range(terminal_i, len(trace)):
            if aborted(trace[j]):
                unknown = True
                break
            if outputs(trace[j]).get('cmd_ack', 0) == 1:
                ack_i = j
                break

        if ack_i is None:
            if not any(aborted(trace[j]) for j in range(terminal_i, len(trace))):
                return (False, trace[terminal_i].get('edge'),
                        'sequence completed but cmd_ack was not asserted; expected exactly one clk cycle')
            continue

        width = 0
        j = ack_i
        while j < len(trace) and outputs(trace[j]).get('cmd_ack', 0) == 1:
            width += trace[j].get('held', 1)
            j += 1

        if width != 1:
            return (False, trace[ack_i].get('edge'),
                    f'cmd_ack was high for {width} clk edges; expected exactly one clk cycle')

    if unknown:
        return (None, None,
                'the command sequence was reset or arbitration-aborted before completion was observable')

    return (True, None,
            'each observed completed START, STOP, READ, or WRITE sequence had a one-clock cmd_ack pulse')

def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def out(row, name):
        return row.get('outputs', {}).get(name, 0)

    def aborted(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1 or
                out(row, 'al') == 1)

    def active(row):
        return any(out(row, name) == 1 for name in sequence_ports)

    completed = 0

    i = 0
    while i < len(trace):
        if not active(trace[i]):
            i += 1
            continue

        start = i
        while i < len(trace) and active(trace[i]):
            i += 1
        end = i

        # The sequence did not reach its end in the observed trace.
        if end == len(trace):
            if any(aborted(trace[j]) for j in range(start, end)):
                continue
            return (None, None,
                    'a START, STOP, READ, or WRITE sequence remained incomplete in the trace')

        # Reset or arbitration loss voids the acknowledgement obligation.
        if any(aborted(trace[j]) for j in range(start, end + 1)):
            continue

        # cmd_ack must not occur before the sequence completion boundary.
        early = [j for j in range(start, end)
                 if out(trace[j], 'cmd_ack') == 1]
        if early:
            return (False, trace[early[0]].get('edge'),
                    'cmd_ack was asserted before the START, STOP, READ, or WRITE sequence ended')

        # The first state after the sequence is its completion state, and the
        # registered acknowledgement must be asserted there.
        if out(trace[end], 'cmd_ack') != 1:
            return (False, trace[end].get('edge'),
                    'at the end of the command sequence cmd_ack was not asserted')

        width = 0
        j = end
        while j < len(trace) and out(trace[j], 'cmd_ack') == 1:
            width += trace[j].get('held', 1)
            j += 1

        if width != 1:
            return (False, trace[end].get('edge'),
                    f'cmd_ack was asserted for {width} clk cycles at sequence completion; expected exactly one')

        completed += 1

    if completed == 0:
        return (None, None,
                'no non-aborted START, STOP, READ, or WRITE sequence reached completion')

    return (True, None,
            f'{completed} completed START, STOP, READ, or WRITE sequence(s) had exactly one clk-cycle cmd_ack pulse')

