def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        prev_outputs = prev.get('outputs', {})

        # A falling active_command probe identifies normal completion.
        # Reset and arbitration loss abort the operation instead.
        if (prev_outputs.get('active_command') == 1
                and outputs.get('active_command') == 0
                and inputs.get('nReset') != 0
                and inputs.get('rst') != 1
                and outputs.get('al') != 1):
            completions.append(i)

    if not completions:
        return (None, None, 'no non-aborted bit-level command completion occurred')

    for i in completions:
        row = trace[i]
        edge = row.get('edge')
        if row.get('outputs', {}).get('cmd_ack') != 1:
            return (False, edge, 'cmd_ack was not high when the bit-level command completed')

        # The pulse must start at completion, not already be high beforehand.
        if (i > 0
                and trace[i - 1].get('outputs', {}).get('cmd_ack') == 1):
            return (False, edge, 'cmd_ack was already high before command completion')

        total_edges = 0
        j = i
        while j < len(trace) and trace[j].get('outputs', {}).get('cmd_ack') == 1:
            total_edges += trace[j].get('held', 0)
            j += 1

        # The trace ended while cmd_ack was still high, so its exact width is
        # not observable yet.
        if j == len(trace):
            return (None, edge, 'cmd_ack pulse remained high at the end of the trace')

        if total_edges != 1:
            return (False, edge, f'cmd_ack was high for {total_edges} clock edges, expected exactly 1')

    return (True, None, f'cmd_ack was a one-clock pulse for {len(completions)} completed command(s)')

def decide(trace):
    active = False
    start = None
    aborted = False
    incomplete = False
    completed = 0

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        is_reset = inputs.get('nReset') == 0 or inputs.get('rst') == 1
        is_active = outputs.get('active_command') == 1
        is_al = outputs.get('al') == 1
        ack = outputs.get('cmd_ack')

        if is_reset:
            active = False
            start = None
            aborted = False
            continue

        if not active:
            if is_active:
                active = True
                start = i
                aborted = is_al
            continue

        if is_al:
            aborted = True

        if is_active:
            if not aborted and ack == 1:
                return (False, row.get('edge'),
                        'cmd_ack was high before the bit-level operation completed')
            continue

        # The active operation has ended.  Arbitration loss makes this an
        # aborted operation rather than a completion.
        if aborted:
            active = False
            start = None
            aborted = False
            continue

        completed += 1
        if ack != 1:
            return (False, row.get('edge'),
                    'cmd_ack was not high when the bit-level operation completed')

        if start is not None and start < i:
            previous_ack = trace[i - 1].get('outputs', {}).get('cmd_ack')
            if previous_ack == 1:
                return (False, row.get('edge'),
                        'cmd_ack was already high before the completion state')

        total_edges = 0
        j = i
        while j < len(trace) and trace[j].get('outputs', {}).get('cmd_ack') == 1:
            total_edges += trace[j].get('held', 0)
            j += 1

        if j == len(trace):
            incomplete = True
        elif total_edges != 1:
            return (False, row.get('edge'),
                    f'cmd_ack was high for {total_edges} clock edges, expected exactly 1')

        active = False
        start = None
        aborted = False

    if active and not aborted:
        incomplete = True

    if completed == 0:
        return (None, None, 'no non-aborted bit-level operation reached completion')
    if incomplete:
        return (None, None, 'a bit-level operation or its cmd_ack pulse was incomplete at the end of the trace')
    return (True, None, f'cmd_ack was a one-clock pulse for {completed} completed bit-level operation(s)')
